test('fresh lives have workplace social life guardianship parenting extended family housing justice romance appearance education mobility yearly ambition and persistent variety profiles',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.ok(run('s.variety&&s.variety.ambition&&s.variety.ambition.target>0'));assert.equal(run('s.variety.ambition.year'),run('s.year+s.age'));});
test('variety ambition counts distinct meaningful actions instead of repeated spam',()=>{const {run}=game();run(setup+'s.age=20;s.variety={activityStats:{},recent:[],completed:[],annualHistory:[],rerolls:0,ambition:{id:"variety",title:"Test",desc:"",target:5,progress:0,year:s.year+s.age,done:false,keys:[],reward:{}}};trackLifeVarietyAction({kind:"period",id:"market"});trackLifeVarietyAction({kind:"period",id:"market"});trackLifeVarietyAction({kind:"training",id:"horse"})');assert.equal(run('s.variety.ambition.progress'),2);});
test('seasonal activities rotate with the calendar month',()=>{const {run}=game();run(setup+'s.age=20;s.monthsRemaining=10');assert.ok(run('seasonalActivitiesNow().some(x=>x.id==="spring_move")'));run('s.monthsRemaining=5');assert.ok(run('seasonalActivitiesNow().some(x=>x.id==="autumn_store")'));assert.ok(run('!seasonalActivitiesNow().some(x=>x.id==="spring_move")'));});
test('repeating the same period activity is remembered and loses novelty',()=>{const {run}=game();run(setup+'s.age=20;s.variety.recent=[{key:"period:bardlisten",year:s.year+s.age,month:1},{key:"period:bardlisten",year:s.year+s.age,month:2},{key:"period:bardlisten",year:s.year+s.age,month:3}];window.__h=s.happiness;window.__note=periodNoveltyBonus("bardlisten")');assert.ok(run('__note.includes("tekrarlamak")'));assert.equal(run('s.happiness'),run('__h-1'));});
test('v8 saves migrate to v25 with variety profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=8;delete s.variety;save();load()');assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.variety&&s.variety.activityStats&&s.variety.ambition'));});
test('migration destinations expose other settlements available in the current year',()=>{const {run}=game();run(setup+'s.age=20;ensureMobility()');assert.ok(run('migrationDestinations().some(x=>x.place!==s.place)'));assert.ok(run('migrationDestinations().every(x=>realmActiveAt(x.realm,s.year+s.age))'));});
test('household migration moves partner and children while preserving tribe identity',()=>{const {run}=game();run(setup+'s.age=25;s.wealth=200;s.partner=normalizeNPC({name:"Es",gender:"female",age:24,alive:true,rel:80,type:"Eş"});s.children=[normalizeNPC({name:"Cocuk",gender:"male",age:4,alive:true,rel:85,type:"Çocuk"})];window.__tribe=s.tribe;window.__dest=migrationDestinations().find(x=>x.realm===s.realm)||migrationDestinations()[0];Math.random=()=>.999;migrateTo(__dest.realm,__dest.place,"household")');assert.equal(run('s.place'),run('__dest.place'));assert.equal(run('s.tribe'),run('__tribe'));assert.equal(run('s.partner.place'),run('__dest.place'));assert.equal(run('s.children[0].place'),run('__dest.place'));assert.equal(run('s.mobility.moves'),1);});
test('moving alone leaves close family behind and strains the relationship',()=>{const {run}=game();run(setup+'s.age=25;s.wealth=200;s.partner=normalizeNPC({name:"Es",gender:"female",age:24,alive:true,rel:80,type:"Eş",place:s.place,realm:s.realm});window.__rel=s.partner.rel;window.__old=s.place;window.__dest=migrationDestinations().find(x=>x.realm===s.realm);Math.random=()=>.999;migrateTo(__dest.realm,__dest.place,"alone")');assert.equal(run('s.partner.place'),run('__old'));assert.ok(run('s.partner.rel<__rel'));});
test('cross realm migration reduces old political influence but does not rewrite tribe',()=>{const {run}=game();run(setup+'s.age=70;s.wealth=300;ensureStateCourt();s.stateCourt.influence=80;s.stateCourt.councilTrust=70;window.__tribe=s.tribe;window.__dest=migrationDestinations().find(x=>x.realm!==s.realm);Math.random=()=>.999');assert.ok(run('!!__dest'));run('migrateTo(__dest.realm,__dest.place,"alone")');assert.equal(run('s.tribe'),run('__tribe'));assert.ok(run('s.stateCourt.influence<=20'));});
test('v9 saves migrate to v25 with mobility profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=9;delete s.mobility;save();load()');assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.mobility&&Array.isArray(s.mobility.history)&&Number.isFinite(s.mobility.localStanding)'));});
test('studying a path creates a persistent mentor peer group and progress',()=>{const {run}=game();run(setup+'s.age=18;s.monthsRemaining=12;studyEducation("smith")');assert.equal(run('s.education.tracks.smith.months'),1);assert.ok(run('!!educationContact(s.education.tracks.smith.mentorId)'));assert.ok(run('s.education.tracks.smith.peerIds.length>=2'));assert.ok(run('s.skills.craft>100?true:s.skills.craft>=100'));});
test('education ranks advance at persistent month thresholds and record evaluations',()=>{const {run}=game();run(setup+'s.age=18;s.monthsRemaining=12;s.skills.craft=100;ensureEducation();s.education.tracks.smith.months=5;Math.random=()=>0;studyEducation("smith")');assert.equal(run('s.education.tracks.smith.months'),6);assert.equal(run('s.education.tracks.smith.rank'),"Temel Öğrenen");assert.equal(run('s.education.tracks.smith.evaluations'),1);assert.ok(run('s.education.tracks.smith.praise>=1'));});
test('education peers can become lasting friends through repeated bonds',()=>{const {run}=game();run(setup+'s.age=18;ensureEducation();educationPeers("story",1);window.__p=educationContact(s.education.tracks.story.peerIds[0]);__p.rel=70;__p.bonds.trust=65;s.monthsRemaining=12;educationInteraction(ensureEducation().contacts.findIndex(x=>x.id===__p.id),"befriend")');assert.ok(run('s.friends.some(x=>x.id===__p.id)'));});
test('deep education gives a career acceptance bonus without bypassing requirements',()=>{const {run}=game();run(setup+'s.age=25;ensureEducation();s.education.tracks.smith.months=60;s.education.tracks.smith.praise=3;window.__r=D.careers.find(x=>x.id==="smith");window.__b=educationFitBonusForCareer(__r)');assert.ok(run('__b>0'));assert.ok(run('__b<=.14'));run('s.skills.craft=0');assert.ok(run('careerIssue(__r).includes("Zanaat")||careerIssue(__r).includes("zanaat")||careerIssue(__r).includes("craft")'));});
test('v10 saves migrate to v25 with education profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=10;delete s.education;save();load()');assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.education&&s.education.tracks&&Array.isArray(s.education.contacts)'));});
test('education mentor and peer can become direct life-event targets',()=>{const {run}=game();run(setup+'s.age=18;ensureEducation();educationMentor("smith",true);educationPeers("smith",2)');assert.ok(run('eventTargetCandidates("educationMentor").some(x=>x.statusFlags.educationTrack==="smith")'));assert.ok(run('eventTargetCandidates("educationPeer").some(x=>x.statusFlags.educationTrack==="smith")'));});
test('education life event choices improve the matching track skill and NPC bond',()=>{const {run}=game();run(setup+'s.age=18;ensureEducation();window.__m=educationMentor("smith",true);s.pendingEventId="education_mentor_trial";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,kind:"education",targetId:__m.id};window.__skill=s.skills.craft;window.__trust=__m.bonds.trust;chooseContextEvent(0)');assert.ok(run('s.skills.craft>=__skill'));assert.ok(run('__m.bonds.trust>__trust'));assert.equal(run('s.pendingEventId'),null);});
test('fresh appearance profile renders a layered portrait instead of an emoji',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.ok(run('s.appearance&&APPEARANCE_OPTIONS.hair.some(x=>x.id===s.appearance.hair)'));assert.ok(run('appearanceAvatarHtml().includes("portrait-head")&&appearanceAvatarHtml().includes("portrait-hair")'));});
test('hair face and headwear customization persists without spending a month',()=>{const {run}=game();run(setup+'window.__m=s.monthsRemaining;setAppearancePart("hair","braid");setAppearancePart("face","broad");setAppearancePart("headwear","bork")');assert.equal(run('s.appearance.hair'),"braid");assert.equal(run('s.appearance.face'),"broad");assert.equal(run('s.appearance.headwear'),"bork");assert.equal(run('s.monthsRemaining'),run('__m'));});
test('appearance ages gradually and frailty can accelerate greying',()=>{const {run}=game();run(setup+'s.age=30;ensureAppearance();ensureHealthProfile();window.__young=appearanceGreyLevel();s.age=68;s.health=35;s.healthProfile.frailty=75;window.__old=appearanceGreyLevel()');assert.ok(run('__old>__young'));assert.ok(run('appearanceAvatarHtml().includes("age-elder")'));});
test('persistent health scars are rendered on the portrait',()=>{const {run}=game();run(setup+'s.age=35;addScar("battle",1,"test");addScar("fall",1,"test")');assert.equal(run('appearanceScarCount()'),2);assert.ok(run('appearanceAvatarHtml().includes("scar-1")&&appearanceAvatarHtml().includes("scar-2")'));});
test('grooming restores appearance care and consumes exactly one month',()=>{const {run}=game();run(setup+'s.age=20;s.appearance.care=25;s.monthsRemaining=12;window.__h=s.happiness;groomAppearance()');assert.equal(run('s.monthsRemaining'),11);assert.ok(run('s.appearance.care>25'));assert.ok(run('s.happiness>__h'));});
test('war headwear stays locked until military identity is earned',()=>{const {run}=game();run(setup+'s.age=20;s.role=null;s.military.served=false');assert.equal(run('appearanceChoiceAllowed("headwear","war")'),false);run('s.military.served=true');assert.equal(run('appearanceChoiceAllowed("headwear","war")'),true);});
test('v11 saves migrate to v25 with appearance profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=11;delete s.appearance;save();load()');assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.appearance&&Number.isFinite(s.appearance.care)&&Array.isArray(s.appearance.history)'));});
test('meeting a partner creates a persistent relationship profile with compatibility and family approval',()=>{const {run}=game();run(setup+'s.age=20;s.monthsRemaining=12;meetPartner()');assert.ok(run('s.partner&&s.romance.current&&s.romance.current.partnerId===s.partner.id'));assert.ok(run('Number.isFinite(s.romance.current.compatibility)&&Number.isFinite(s.romance.current.familyApproval)'));});
test('relationship actions change distinct harmony commitment and tension values',()=>{const {run}=game();run(setup+'s.age=20;s.monthsRemaining=12;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;window.__h=s.romance.current.harmony;window.__c=s.romance.current.commitment;relationshipAction("time");s.pendingEventId=null;s.pendingEventContext=null;relationshipAction("future")');assert.ok(run('s.romance.current.harmony>__h'));assert.ok(run('s.romance.current.commitment>__c'));});
test('family introduction raises approval and creates partner-to-kin social links',()=>{const {run}=game();run(setup+'s.age=20;s.monthsRemaining=12;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;window.__a=s.romance.current.familyApproval;relationshipAction("family")');assert.ok(run('s.romance.current.familyApproval>__a'));assert.ok(run('s.parents.some(p=>!!socialLinkBetween(p,s.partner))'));});
test('marriage chance benefits from relationship depth but still uses partner requirements',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;s.partner.age=24;s.partner.rel=90;s.partner.bonds.trust=90;s.romance.current.commitment=95;s.romance.current.harmony=90;s.romance.current.familyApproval=90;s.romance.current.tension=0;Math.random=()=>0;marry()');assert.ok(run('s.married'));assert.equal(run('s.romance.current.stage'),"married");});
test('ending a relationship preserves the ex and archived relationship history',()=>{const {run}=game();run(setup+'s.age=24;s.monthsRemaining=12;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;window.__id=s.partner.id;endRelationship()');assert.ok(run('!s.partner'));assert.ok(run('s.exPartners.some(x=>x.id===__id)'));assert.ok(run('s.romance.history.some(x=>x.partnerId===__id)'));});
test('an ex can be reconciled into a new courtship when trust is high',()=>{const {run}=game();run(setup+'s.age=24;s.monthsRemaining=12;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;window.__id=s.partner.id;endRelationship();s.pendingEventId=null;s.pendingEventContext=null;s.exPartners[0].rel=90;s.exPartners[0].bonds.trust=90;s.exPartners[0].bonds.grudge=0;Math.random=()=>0;reconcileEx(0)');assert.equal(run('s.partner.id'),run('__id'));assert.equal(run('s.married'),false);assert.equal(run('s.romance.current.stage'),"courtship");});
test('neglect distance and jealousy can create transparent relationship tension',()=>{const {run}=game();run(setup+'s.age=25;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;s.partner.place="Uzak Yer";window.__t=s.romance.current.tension;for(let i=0;i<6;i++)tickRomanceMonth({kind:"wait"});window.__j=s.romance.current.jealousy;tickRomanceMonth({kind:"npc",group:"friends",id:"confide"})');assert.ok(run('s.romance.current.tension>__t'));assert.ok(run('s.romance.current.jealousy>__j'));});
test('relationship crisis events target the current partner and can reduce tension',()=>{const {run}=game();run(setup+'s.age=25;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;s.romance.current.tension=70;window.__p=s.partner;window.__t=s.romance.current.tension;s.pendingEventId="romance_household_strain";s.married=true;s.romance.current.stage="married";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,kind:"romance",targetId:__p.id};chooseContextEvent(0)');assert.ok(run('s.romance.current.tension<__t'));assert.equal(run('s.pendingEventId'),null);});
test('v12 saves migrate to v25 with relationship profile ex list and dedicated backup',()=>{const {run,storage}=game();run('s.version=12;delete s.romance;delete s.exPartners;save();load()');assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.romance&&Array.isArray(s.exPartners)'));});
test('fresh lives carry a persistent justice profile',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.ok(run('s.justice&&Array.isArray(s.justice.cases)&&Array.isArray(s.justice.contacts)&&Number.isFinite(s.justice.suspicion)'));});
test('a crime creates a persistent victim case and enriched crime record',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;Math.random=()=>.99;commitCrime("horse_theft")');assert.ok(run('s.justice.cases.length===1'));assert.ok(run('!!justiceContact(s.justice.cases[0].victimId)'));assert.equal(run('s.crimeRecord[0].id'),run('s.justice.cases[0].id'));assert.ok(run('Number.isFinite(s.crimeRecord[0].evidence)'));});
test('an exposed crime becomes an open tore case and blocks stacking another crime',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;Math.random=()=>0;commitCrime("flock_theft");s.pendingEventId=null;s.pendingEventContext=null;s.pendingDecision=null');assert.equal(run('s.justice.cases[0].status'),"summoned");assert.ok(run('accessIssue({kind:"crime",id:"horse_theft"}).includes("açık töre")'));});
test('mediation can turn a summons into a payable negotiated settlement',()=>{const {run}=game();run(setup+'s.age=30;s.wealth=100;ensureJustice();window.__v=crimeVictimFor(CRIME_PROFILES.horse_theft);window.__c={id:"c1",crimeId:"horse_theft",name:"At Çal",victimId:__v.id,witnessIds:[],severity:54,evidence:40,status:"summoned",restitutionDue:0,mediationBonus:0};s.justice.cases=[__c];s.pendingEventId=null;s.pendingDecision=null;Math.random=()=>0;justiceCaseAction("c1","mediate")');assert.equal(run('__c.status'),"settlement_due");assert.ok(run('__c.restitutionDue>0'));});
test('paying restitution settles the case and reduces suspicion and victim grudge',()=>{const {run}=game();run(setup+'s.age=30;s.wealth=100;ensureJustice();window.__v=crimeVictimFor(CRIME_PROFILES.flock_theft);__v.bonds.grudge=70;window.__c={id:"c2",crimeId:"flock_theft",name:"Sürü Çal",victimId:__v.id,witnessIds:[],severity:46,evidence:35,status:"settlement_due",restitutionDue:12,mediationBonus:0};s.justice.cases=[__c];s.justice.suspicion=60;window.__g=__v.bonds.grudge;justiceCaseAction("c2","pay")');assert.equal(run('__c.status'),"settled");assert.ok(run('s.justice.suspicion<60'));assert.ok(run('__v.bonds.grudge<__g'));assert.equal(run('s.wealth'),88);});
test('a severe proved case can produce exile or captivity when restitution cannot be met',()=>{const {run}=game();run(setup+'s.age=30;s.wealth=0;ensureJustice();window.__v=crimeVictimFor(CRIME_PROFILES.illegal_raid);window.__w=makeJusticeNPC("Tanık");window.__c={id:"c3",crimeId:"illegal_raid",name:"İzinsiz Yağmaya Katıl",victimId:__v.id,witnessIds:[__w.id],severity:90,evidence:100,status:"summoned",restitutionDue:30,mediationBonus:0};s.justice.cases=[__c];s.justice.suspicion=80;s.pendingEventId=null;s.pendingDecision=null;Math.random=()=>0;justiceCaseAction("c3","hearing")');assert.ok(run('s.captive||s.exile'));assert.equal(run('__c.status'),"judged");});
test('old crime accusations stay attached to their original case and victim',()=>{const {run}=game();run(setup+'s.age=30;ensureJustice();window.__v=crimeVictimFor(CRIME_PROFILES.horse_theft);window.__c={id:"old1",crimeId:"horse_theft",name:"At Çal",victimId:__v.id,witnessIds:[],severity:54,evidence:45,status:"hidden",restitutionDue:0,mediationBonus:0};s.justice.cases=[__c];s.delayedEvents=[{id:"d1",eventId:"crime_old_accusation",dueYear:s.year+s.age,createdYear:s.year+s.age-3,targetId:__v.id,otherTargetId:null,sourceEventId:"crime:horse_theft",status:"pending",payload:{caseId:"old1",detail:"Eski mesele."}}];s.pendingEventId="crime_old_accusation";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,kind:"wait",targetId:__v.id,otherTargetId:null,delayedId:"d1",delayedPayload:{caseId:"old1",detail:"Eski mesele."}};chooseContextEvent(0)');assert.equal(run('__c.status'),"summoned");assert.equal(run('s.delayedEvents.find(x=>x.id==="d1").status'),"resolved");});
test('serious victim harm can create a persistent family feud that reconciliation cools',()=>{const {run}=game();run(setup+'s.age=30;ensureJustice();window.__v=crimeVictimFor(CRIME_PROFILES.illegal_raid);window.__c={id:"f1",crimeId:"illegal_raid",name:"İzinsiz Yağmaya Katıl",victimId:__v.id,witnessIds:[],severity:78,evidence:60,status:"settled",restitutionDue:0,mediationBonus:0};s.justice.cases=[__c];markJusticeHostility(__c,78);window.__f=justiceFeudForCase(__c,true);window.__heat=__f.heat;s.pendingEventId=null;s.pendingDecision=null;justiceCaseAction("f1","reconcile")');assert.ok(run('__f.heat<__heat'));assert.ok(run('!!justiceContact(__f.kinId)'));});
test('v13 saves migrate to v25 with justice profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=13;delete s.justice;save();load()');assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.justice&&Array.isArray(s.justice.cases)&&Array.isArray(s.justice.feuds)'));});
test('fresh lives start in a persistent family housing profile',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.ok(run('s.housing&&s.housing.mode==="family_yurt"'));assert.ok(run('housingResidentCount()>=2'));assert.ok(run('housingCapacity()>=4'));});
test('owning a yurt allows an adult to establish a separate household with spouse and children',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;s.assets.push("yurt");assetState("yurt").condition=90;s.partner=normalizeNPC({name:"Es",gender:"female",age:24,alive:true,rel:80,type:"Eş",place:s.place,realm:s.realm});s.married=true;s.children=[normalizeNPC({name:"Cocuk",gender:"male",age:3,alive:true,rel:80,type:"Çocuk",place:s.place,realm:s.realm})];ensureHousing().mode="family_yurt";housingAction("establish")');assert.equal(run('s.housing.mode'),"own_yurt");assert.equal(run('s.monthsRemaining'),11);assert.ok(run('housingResidents().some(x=>x.id===s.partner.id)'));assert.ok(run('housingResidents().some(x=>x.id===s.children[0].id)'));});
test('expanding an independent yurt costs wealth and increases capacity by two',()=>{const {run}=game();run(setup+'s.age=25;s.wealth=100;s.assets.push("yurt");ensureHousing().mode="own_yurt";window.__cap=housingCapacity();window.__cost=housingExpansionCost();s.monthsRemaining=12;housingAction("expand")');assert.equal(run('housingCapacity()'),run('__cap+2'));assert.equal(run('s.wealth'),run('100-__cost'));assert.equal(run('s.housing.expansions'),1);});
test('overcrowded housing creates quarterly happiness and health pressure',()=>{const {run}=game();run(setup+'s.age=30;s.assets.push("yurt");ensureHousing().mode="own_yurt";s.partner=normalizeNPC({name:"Es",gender:"female",age:29,alive:true,type:"Eş",rel:80});s.married=true;s.children=[];for(let i=0;i<5;i++)s.children.push(normalizeNPC({name:"C"+i,gender:i%2?"female":"male",age:5+i,alive:true,type:"Çocuk",rel:80}));window.__h=s.health;window.__m=s.happiness;tickHousingMonth(3,{kind:"wait"})');assert.ok(run('housingCrowding()>=3'));assert.ok(run('s.happiness<__m'));assert.ok(run('s.health<__h'));});
test('temporary winter shelter has direct health and happiness consequences',()=>{const {run}=game();run(setup+'s.age=25;ensureHousing().mode="temporary_shelter";s.housing.temporaryQuality=20;window.__h=s.health;window.__m=s.happiness;Math.random=()=>.99;tickHousingMonth(12,{kind:"wait"})');assert.ok(run('s.health<__h'));assert.ok(run('s.happiness<__m'));assert.equal(run('s.housing.monthsUnsheltered'),1);});
test('a trusted nearby relative can take the player into a hosted yurt',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;ensureHousing().mode="temporary_shelter";s.parents[0].rel=80;normalizeBonds(s.parents[0]);s.parents[0].bonds.trust=80;s.parents[0].place=s.place;s.parents[0].realm=s.realm;Math.random=()=>0;housingAction("seek_host")');assert.equal(run('s.housing.mode'),"hosted_yurt");assert.equal(run('s.housing.hostId'),run('s.parents[0].id'));});
test('migration without a yurt creates temporary shelter while taking a yurt preserves independent housing',()=>{const {run}=game();run(setup+'s.age=25;s.wealth=300;ensureHousing().mode="family_yurt";window.__d=migrationDestinations().find(x=>x.realm===s.realm);Math.random=()=>.999;migrateTo(__d.realm,__d.place,"alone")');assert.equal(run('s.housing.mode'),"temporary_shelter");run('s.pendingEventId=null;s.pendingEventContext=null;s.pendingDecision=null;s.assets.push("yurt");ensureHousing().mode="temporary_shelter";window.__d2=migrationDestinations().find(x=>x.realm===s.realm);migrateTo(__d2.realm,__d2.place,"alone")');assert.equal(run('s.housing.mode'),"own_yurt");});
test('the currently inhabited independent yurt cannot be sold out from under the household',()=>{const {run}=game();run(setup+'s.age=25;s.assets.push("yurt");ensureHousing().mode="own_yurt"');assert.ok(run('accessIssue({kind:"asset",id:"yurt",sell:true}).includes("başka barınma")'));});
test('severe family-home pressure can force an unsupported adult into temporary shelter',()=>{const {run}=game();run(setup+'s.age=28;s.role=null;s.assets=s.assets.filter(x=>x!=="yurt");ensureHousing().mode="family_yurt";s.housing.pressure=82;s.parents.forEach(p=>{p.rel=20;});housingYearTick()');assert.equal(run('s.housing.mode'),"temporary_shelter");assert.ok(run('s.housing.history.some(x=>x.note.includes("ayrılmak zorunda"))'));});
test('v14 saves migrate to v25 with housing profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=14;delete s.housing;save();load()');assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.housing&&Array.isArray(s.housing.history)&&Number.isFinite(s.housing.comfort)'));});
test('fresh lives keep a persistent extended family profile and seeded blood relatives',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.ok(run('s.extendedFamily&&Array.isArray(s.extendedFamily.inLaws)&&Array.isArray(s.extendedFamily.history)'));assert.ok(run('(s.relatives||[]).some(x=>["Dede","Nine"].includes(x.type))'));});
test('meeting a partner creates persistent parents and sibling in-laws tied to that partner',()=>{const {run}=game();run(setup+'s.age=22;s.monthsRemaining=12;meetPartner()');assert.ok(run('s.extendedFamily.inLaws.filter(x=>x.statusFlags.inLawRoot).length===2'));assert.ok(run('s.extendedFamily.inLaws.every(x=>x.statusFlags.partnerFamilyFor===s.partner.id)'));assert.ok(run('s.partner.parentIds.length===2'));});
test('breaking up preserves the former partner family as historical in-laws instead of deleting them',()=>{const {run}=game();run(setup+'s.age=22;s.monthsRemaining=12;meetPartner();s.pendingEventId=null;s.pendingEventContext=null;window.__pid=s.partner.id;endRelationship()');assert.ok(run('s.extendedFamily.inLaws.some(x=>x.statusFlags.legacyInLaw&&x.statusFlags.partnerFamilyFor===__pid)'));assert.ok(run('s.extendedFamily.inLaws.every(x=>!x.statusFlags.inLaw)'));});
test('cousins and sibling children receive player-relative kin roles in the visible extended family',()=>{const {run}=game();run(setup+'s.age=25;window.__a=s.relatives.find(x=>["Amca","Hala","Dayı","Teyze"].includes(x.type));if(!__a){__a=normalizeNPC({name:"Amca",gender:"male",age:45,alive:true,type:"Amca",parentIds:[s.relatives.find(x=>x.type==="Dede").id]});s.relatives.push(__a)};window.__c=normalizeNPC({name:"Kuzen",gender:"male",age:20,alive:true,type:"Çocuk",parentIds:[__a.id]});__a.descendants.push(__c);window.__sib=s.siblings[0]||normalizeNPC({name:"Kardes",gender:"female",age:23,alive:true,type:"Kız kardeş",parentIds:s.parents.map(x=>x.id)});if(!s.siblings.length)s.siblings.push(__sib);window.__n=normalizeNPC({name:"Yegen",gender:"female",age:2,alive:true,type:"Çocuk",parentIds:[__sib.id]});__sib.descendants.push(__n)');assert.equal(run('kinRole(__c)'),"Kuzen");assert.equal(run('kinRole(__n)'),"Yeğen");assert.ok(run('extendedFamilyVisible().some(x=>x.id===__c.id)&&extendedFamilyVisible().some(x=>x.id===__n.id)'));});
test('a family reunion changes real family bonds and is recorded in history',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;window.__n=extendedFamilyVisible().find(x=>x.alive&&x.place===s.place)||s.relatives.find(x=>x.alive);__n.place=s.place;__n.realm=s.realm;window.__r=__n.rel;Math.random=()=>.99;extendedFamilyAction("reunion")');assert.equal(run('s.extendedFamily.reunions'),1);assert.ok(run('__n.rel>=__r'));assert.ok(run('s.extendedFamily.history.some(x=>x.type==="reunion")'));});
test('support given to extended kin consumes wealth and builds trust',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;s.wealth=20;window.__n=extendedFamilyVisible().find(x=>x.alive);window.__i=extendedFamilyVisible().findIndex(x=>x.id===__n.id);window.__t=__n.bonds.trust;extendedFamilyAction("support",__i)');assert.equal(run('s.wealth'),17);assert.ok(run('__n.bonds.trust>__t'));assert.equal(run('s.extendedFamily.supportGiven'),3);});
test('trusted wealthy extended kin can provide direct family support',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;window.__n=extendedFamilyVisible().find(x=>x.alive);window.__i=extendedFamilyVisible().findIndex(x=>x.id===__n.id);__n.rel=90;__n.wealth=40;__n.bonds.trust=90;window.__w=s.wealth;Math.random=()=>0;extendedFamilyAction("ask_help",__i)');assert.ok(run('s.wealth>__w'));assert.ok(run('s.extendedFamily.supportReceived>0'));});
test('a wealthy close elder relative enters the real estate pipeline exactly once',()=>{const {run}=game();run(setup+'s.age=30;window.__g=s.relatives.find(x=>["Dede","Nine"].includes(x.type));__g.wealth=50;__g.rel=90;__g.alive=false;window.__e=maybeExtendedInheritance(__g);window.__again=maybeExtendedInheritance(__g)');assert.ok(run('__e&&["settled","disputed","unclaimed"].includes(__e.status)'));assert.equal(run('__again&&__again.id'),run('__e.id'));assert.equal(run('__g.statusFlags.inheritanceHandled'),true);assert.ok(run('s.npcEstates.cases.some(x=>x.id===__e.id)'));});
test('extended family branch growth is capped to protect long legacy saves',()=>{const {run}=game();run(setup+'ensureExtendedFamily().branchLimit=50;for(let i=0;i<55;i++)s.relatives.push(normalizeNPC({name:"R"+i,gender:i%2?"female":"male",age:20,alive:true,type:"Kuzen"}))');assert.equal(run('familyBranchCanGrow()'),false);});
test('continuing as a child converts the old spouses family into grandparents and aunts or uncles',()=>{const {run}=game();run(setup+'s.age=40;s.monthsRemaining=0;s.partner=normalizeNPC({name:"Es",gender:"female",age:38,alive:true,rel:80,type:"Eş",realm:s.realm,place:s.place,tribe:s.tribe});s.married=true;ensureExtendedFamily().partnerFamilyFor=null;ensurePartnerFamily(true);window.__roots=s.extendedFamily.inLaws.filter(x=>x.statusFlags.inLawRoot).map(x=>x.id);window.__kid=normalizeNPC({name:"Varis",gender:"male",age:20,alive:true,rel:85,type:"Çocuk",birthYear:s.year+s.age-20,parentIds:[s.id,s.partner.id],descendants:[]});s.children=[__kid];s.will=__kid.id;s.alive=false;s.deathRecord={name:s.name,age:s.age,year:s.year+s.age,assets:[],heirs:[{id:__kid.id,name:__kid.name,age:__kid.age}]};continueAsHeir(0)');assert.ok(run('__roots.every(id=>s.relatives.some(x=>x.id===id&&["Dede","Nine"].includes(x.type)))'));assert.ok(run('s.extendedFamily&&Array.isArray(s.extendedFamily.inLaws)'));});
test('v15 saves migrate to v25 with extended family profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=15;delete s.extendedFamily;save();load()');assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.extendedFamily&&Array.isArray(s.extendedFamily.inLaws)&&Number.isFinite(s.extendedFamily.branchLimit)'));});
test('fresh lives carry a persistent parenting profile ready for future children',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.ok(run('s.parenting&&s.parenting.children&&Array.isArray(s.parenting.history)'));});
test('newborn children receive parent ids and an individual upbringing profile',()=>{const {run}=game();run(setup+'s.age=25;s.partner=normalizeNPC({name:"Es",gender:"female",age:24,alive:true,type:"Eş",rel:80});s.married=true;s.pregnancy={remaining:1};s.monthsRemaining=12;monthlyTick(1,{kind:"wait"},false)');assert.equal(run('s.children.length'),1);assert.ok(run('s.children[0].parentIds.includes(s.id)&&s.children[0].parentIds.includes(s.partner.id)'));assert.ok(run('!!childProfile(s.children[0].id)'));});
test('direct care raises warmth attention wellbeing and child trust while consuming one month',()=>{const {run}=game();run(setup+'s.age=28;s.monthsRemaining=12;window.__c=normalizeNPC({name:"C",gender:"male",age:5,alive:true,type:"Çocuk",rel:60,parentIds:[s.id]});s.children=[__c];window.__p=ensureChildProfile(__c);__p.warmth=40;__p.attention=40;__p.wellbeing=40;window.__t=__c.bonds.trust;parentingAction(0,"care")');assert.equal(run('s.monthsRemaining'),11);assert.ok(run('__p.warmth>40&&__p.attention>40&&__p.wellbeing>40'));assert.ok(run('__c.bonds.trust>__t'));});
test('strict discipline without warmth can increase fear and lower wellbeing',()=>{const {run}=game();run(setup+'s.age=30;s.monthsRemaining=12;window.__c=normalizeNPC({name:"C",gender:"female",age:10,alive:true,type:"Çocuk",rel:60,parentIds:[s.id]});s.children=[__c];window.__p=ensureChildProfile(__c);__p.warmth=25;__p.wellbeing=60;window.__f=__c.bonds.fear;parentingAction(0,"discipline")');assert.ok(run('__c.bonds.fear>__f'));assert.ok(run('__p.wellbeing<60'));});
test('guidance creates a persistent child path and teaching develops matching skills',()=>{const {run}=game();run(setup+'s.age=32;s.monthsRemaining=12;window.__c=normalizeNPC({name:"C",gender:"male",age:11,alive:true,type:"Çocuk",rel:70,parentIds:[s.id],skills:{}});s.children=[__c];ensureChildProfile(__c);parentingAction(0,"guide","war");s.pendingEventId=null;s.pendingEventContext=null;window.__before=__c.skills.archery||0;parentingAction(0,"teach")');assert.equal(run('childProfile(__c).guidance'),"war");assert.equal(run('__c.goal'),"war");assert.ok(run('(__c.skills.archery||0)>=__before'));});
test('legacy child training story choices write into the same parenting guidance profile',()=>{const {run}=game();run(setup+'s.age=35;window.__c=normalizeNPC({name:"C",gender:"male",age:12,alive:true,type:"Çocuk",rel:75,parentIds:[s.id]});s.children=[__c];ensureChildProfile(__c);s.pendingEventId="child_training_choice";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,kind:"wait",targetId:__c.id};chooseContextEvent(1)');assert.equal(run('childProfile(__c).guidance'),"craft");assert.equal(run('__c.statusFlags.guidance'),"craft");});
test('long neglect reduces attention wellbeing and eventually child trust',()=>{const {run}=game();run(setup+'s.age=34;window.__c=normalizeNPC({name:"C",gender:"female",age:8,alive:true,type:"Çocuk",rel:70,parentIds:[s.id]});s.children=[__c];window.__p=ensureChildProfile(__c);__p.attention=60;__p.wellbeing=70;window.__t=__c.bonds.trust;for(let i=0;i<12;i++)tickParentingMonth({kind:"wait"})');assert.ok(run('__p.attention<60&&__p.wellbeing<70'));assert.ok(run('__c.bonds.trust<__t'));});
test('unequal attention can build sibling rivalry and mediation reduces both rivalry and social grudge',()=>{const {run}=game();run(setup+'s.age=35;s.monthsRemaining=12;window.__a=normalizeNPC({name:"A",gender:"male",age:10,alive:true,type:"Çocuk",rel:70,parentIds:[s.id]});window.__b=normalizeNPC({name:"B",gender:"female",age:8,alive:true,type:"Çocuk",rel:70,parentIds:[s.id]});s.children=[__a,__b];window.__pa=ensureChildProfile(__a);window.__pb=ensureChildProfile(__b);__pa.attention=90;__pb.attention=30;__pb.rivalry=55;window.__link=socialLinkBetween(__a,__b,true,{tags:["kin"]});__link.grudge=20;window.__r=__pb.rivalry;parentingAction(1,"mediate")');assert.ok(run('__pb.rivalry<__r'));assert.ok(run('__link.grudge<20'));});
test('upbringing milestones shape personality goal and adult role at age eighteen',()=>{const {run}=game();run(setup+'s.age=45;window.__c=normalizeNPC({name:"C",gender:"male",age:17,alive:true,type:"Çocuk",rel:80,parentIds:[s.id],traits:["sakin"],skills:{archery:10,riding:10,combat:10}});s.children=[__c];window.__p=ensureChildProfile(__c);__p.guidance="war";__p.warmth=75;__p.attention=80;__p.wellbeing=80;__p.expectation=70;__p.teachingMonths=24;__c.age=18;Math.random=()=>0;applyParentingDevelopment(__c,__p,18)');assert.equal(run('__c.goal'),"war");assert.ok(run('__p.milestones.some(x=>x.age===18)'));assert.ok(run('["Alp","Avcı","Akıncı"].includes(__c.role)'));assert.ok(run('__c.traits.includes("cesur")||__c.traits.includes("caliskan")'));});
test('v16 saves migrate to v25 with parenting profiles for existing children and dedicated backup',()=>{const {run,storage}=game();run('s.version=16;window.__c=normalizeNPC({name:"EskiCocuk",gender:"male",age:7,alive:true,type:"Çocuk",rel:70});s.children=[__c];delete s.parenting;save();load()');assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.parenting&&!!s.parenting.children[s.children[0].id]'));assert.ok(run('s.children[0].parentIds.includes(s.id)'));});
test('fresh minor lives keep an inactive guardianship profile while a parent is alive',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.ok(run('s.guardianship&&Array.isArray(s.guardianship.history)'));assert.equal(run('s.guardianship.active'),false);});
test('an orphaned minor is placed with the strongest available adult relative before an oba guardian is created',()=>{const {run}=game();run(setup+'s.age=10;s.parents.forEach(p=>p.alive=false);s.siblings=[];s.friends=[];s.relatives=[normalizeNPC({name:"Nine",gender:"female",age:58,alive:true,type:"Nine",rel:90,wealth:30,place:s.place,realm:s.realm,traits:["merhametli","sadik"]},"Nine")];s.extendedFamily={inLaws:[],history:[],reunions:0,supportGiven:0,supportReceived:0,branchLimit:90};window.__g=s.relatives[0];normalizeBonds(__g);__g.bonds.trust=90;ensureMinorGuardianship("test kaybı")');assert.equal(run('s.guardianship.active'),true);assert.equal(run('s.guardianship.guardianId'),run('__g.id'));assert.equal(run('s.housing.mode'),"hosted_yurt");assert.equal(run('s.housing.hostId'),run('__g.id'));});
test('when no adult kin or family friend exists the oba supplies a persistent guardian',()=>{const {run}=game();run(setup+'s.age=9;s.parents.forEach(p=>p.alive=false);s.siblings=[];s.relatives=[];s.friends=[];s.extendedFamily={inLaws:[],history:[],reunions:0,supportGiven:0,supportReceived:0,branchLimit:90};ensureMinorGuardianship("yalnız kalma")');assert.ok(run('currentGuardian()&&currentGuardian().type==="Oba Koruyucusu"'));assert.ok(run('s.guardianship.contacts.some(x=>x.id===s.guardianship.guardianId)'));assert.ok(run('s.friends.some(x=>x.id===s.guardianship.guardianId)'));});
test('guardian capacity keeps as many minor siblings together as possible and records separation',()=>{const {run}=game();run(setup+'s.age=8;s.parents.forEach(p=>p.alive=false);s.friends=[];window.__g=normalizeNPC({name:"Dede",gender:"male",age:60,alive:true,type:"Dede",rel:90,wealth:0,place:s.place,realm:s.realm,traits:["merhametli","sakin"]},"Dede");normalizeBonds(__g);__g.bonds.trust=90;s.relatives=[__g];s.siblings=[];for(let i=0;i<4;i++)s.siblings.push(normalizeNPC({name:"K"+i,gender:i%2?"female":"male",age:5+i,alive:true,type:i%2?"Kız kardeş":"Erkek kardeş",rel:75,place:s.place,realm:s.realm},"Kardeş"));s.extendedFamily={inLaws:[],history:[],reunions:0,supportGiven:0,supportReceived:0,branchLimit:90};assignGuardian("test",__g.id)');assert.equal(run('s.guardianship.togetherSiblingIds.length'),2);assert.equal(run('s.guardianship.separatedSiblingIds.length'),2);assert.ok(run('s.guardianship.history[0].separated.length===2'));});
test('time with a guardian improves stability and the guardian bond while consuming one month',()=>{const {run}=game();run(setup+'s.age=10;s.parents.forEach(p=>p.alive=false);s.siblings=[];window.__g=normalizeNPC({name:"Hala",gender:"female",age:36,alive:true,type:"Hala",rel:80,wealth:20,place:s.place,realm:s.realm,traits:["merhametli","sadik"]},"Hala");s.relatives=[__g];normalizeBonds(__g);__g.bonds.trust=70;s.extendedFamily={inLaws:[],history:[],reunions:0,supportGiven:0,supportReceived:0,branchLimit:90};assignGuardian("test",__g.id);s.monthsRemaining=12;window.__st=s.guardianship.stability;window.__t=__g.bonds.trust;guardianshipAction("time")');assert.equal(run('s.monthsRemaining'),11);assert.ok(run('s.guardianship.stability>__st'));assert.ok(run('__g.bonds.trust>__t'));});
test('high quality guardianship can support child health and happiness over time',()=>{const {run}=game();run(setup+'s.age=10;s.parents.forEach(p=>p.alive=false);s.siblings=[];window.__g=normalizeNPC({name:"Dayi",gender:"male",age:40,alive:true,type:"Dayı",rel:95,wealth:50,health:95,place:s.place,realm:s.realm,traits:["merhametli","sadik"]},"Dayı");s.relatives=[__g];normalizeBonds(__g);__g.bonds.trust=95;s.extendedFamily={inLaws:[],history:[],reunions:0,supportGiven:0,supportReceived:0,branchLimit:90};assignGuardian("test",__g.id);s.guardianship.careQuality=90;s.health=60;s.happiness=50;window.__h=s.health;window.__m=s.happiness;s.guardianship.months=2;tickGuardianshipMonth({kind:"wait"})');assert.ok(run('s.health>=__h'));assert.ok(run('s.happiness>__m'));});
test('a dead guardian is replaced by the next suitable adult relative without losing guardianship history',()=>{const {run}=game();run(setup+'s.age=11;s.parents.forEach(p=>p.alive=false);s.siblings=[];window.__a=normalizeNPC({name:"A",gender:"female",age:42,alive:true,type:"Teyze",rel:90,wealth:20,place:s.place,realm:s.realm,traits:["merhametli","sadik"]},"Teyze");window.__b=normalizeNPC({name:"B",gender:"male",age:45,alive:true,type:"Dayı",rel:85,wealth:20,place:s.place,realm:s.realm,traits:["merhametli","caliskan"]},"Dayı");s.relatives=[__a,__b];normalizeBonds(__a);normalizeBonds(__b);__a.bonds.trust=90;__b.bonds.trust=85;s.extendedFamily={inLaws:[],history:[],reunions:0,supportGiven:0,supportReceived:0,branchLimit:90};assignGuardian("ilk",__a.id);window.__old=s.guardianship.guardianId;__a.alive=false;ensureMinorGuardianship("koruyucu kaybı")');assert.ok(run('s.guardianship.guardianId!==__old'));assert.equal(run('s.guardianship.guardianId'),run('__b.id'));assert.ok(run('s.guardianship.transitions>=1'));});
test('separated siblings are valid guardianship event targets and visits rebuild their bond',()=>{const {run}=game();run(setup+'s.age=9;s.parents.forEach(p=>p.alive=false);s.friends=[];window.__g=normalizeNPC({name:"Dede",gender:"male",age:60,alive:true,type:"Dede",rel:90,wealth:0,place:s.place,realm:s.realm,traits:["merhametli","sakin"]},"Dede");s.relatives=[__g];normalizeBonds(__g);__g.bonds.trust=90;s.siblings=[];for(let i=0;i<4;i++)s.siblings.push(normalizeNPC({name:"S"+i,gender:"male",age:4+i,alive:true,type:"Erkek kardeş",rel:60,place:s.place,realm:s.realm},"Erkek kardeş"));s.extendedFamily={inLaws:[],history:[],reunions:0,supportGiven:0,supportReceived:0,branchLimit:90};assignGuardian("test",__g.id);window.__sib=eventTargetCandidates("separatedSibling")[0];window.__idx=s.siblings.filter(n=>n.alive&&s.guardianship.separatedSiblingIds.includes(n.id)).findIndex(x=>x.id===__sib.id);window.__r=__sib.rel;s.monthsRemaining=12;guardianshipAction("visitSibling",__idx)');assert.ok(run('__sib.rel>__r'));assert.ok(run('eventTargetCandidates("guardian")[0].id===s.guardianship.guardianId'));});
