test('finishing a shared project records completion and rewards standing and prestige',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);s.workplace.projectProgress=96;s.prestige=50;window.__pr=s.prestige;tickWorkplaceMonth({kind:"work"})');assert.equal(run('s.workplace.projects'),1);assert.equal(run('s.workplace.projectProgress'),0);assert.ok(run('s.prestige>__pr'));});
test('peer competition can create a persistent workplace rival instead of a disposable event actor',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);window.__n=workplacePeers()[0];window.__i=currentWorkplaceContacts().findIndex(x=>x.id===__n.id);__n.bonds.grudge=34;Math.random=()=>0;workplaceAction(__i,"compete")');assert.ok(run('s.rivals.some(x=>x.id===__n.id)'));assert.ok(run('allNPCs().some(x=>x.id===__n.id)'));});
test('a workplace relationship can naturally turn the same coworker into a friend',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);window.__n=workplacePeers()[0];window.__i=currentWorkplaceContacts().findIndex(x=>x.id===__n.id);__n.rel=70;__n.bonds.trust=65;workplaceAction(__i,"befriend")');assert.ok(run('s.friends.some(x=>x.id===__n.id)'));assert.ok(run('!!s.socialLife.profiles[__n.id]'));});
test('senior workplace rank creates a junior and mentoring develops that same NPC',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);s.workplace.rank=2;workplaceYearTick();window.__n=workplaceJuniors()[0];window.__i=currentWorkplaceContacts().findIndex(x=>x.id===__n.id);window.__respect=__n.bonds.respect;window.__skill=__n.skills[careerPrimarySkill(__r)]||0;s.monthsRemaining=12;workplaceAction(__i,"mentor")');assert.ok(run('!!__n'));assert.ok(run('__n.bonds.respect>__respect'));assert.ok(run('(__n.skills[careerPrimarySkill(__r)]||0)>__skill'));});
