test('opening a council proposal creates stances for real persistent state NPCs and spends a month',()=>{const {run}=game();run(setup+'s.age=36;s.monthsRemaining=12;s.role="Boy Beyi";s.skills.speech=80;s.prestige=80;window.__circle=ensureStateCircle();window.__q=ensureStateCourt();__q.influence=80;__q.councilTrust=80;__q.tribeSupport=80;__q.rivalPressure=10;window.__m=s.monthsRemaining;stateOpenProposal("winter_share");window.__p=currentStateProposal()');assert.equal(run('__p.id'),"winter_share");assert.equal(run('Object.keys(__p.stances).length'),3);assert.ok(run('Object.keys(__p.stances).every(id=>!!npcById(id))'));assert.equal(run('__m-s.monthsRemaining'),1);});

test('high-support council vote passes deterministically and creates a multi-year policy',()=>{const {run}=game();run(setup+'s.age=36;s.monthsRemaining=12;s.role="Boy Beyi";s.skills.speech=90;s.prestige=90;window.__circle=ensureStateCircle();window.__q=ensureStateCourt();__q.influence=90;__q.councilTrust=90;__q.tribeSupport=90;__q.rivalPressure=5;for(const n of [__circle.patron,__circle.rival,__circle.elder]){n.rel=95;n.bonds.trust=95;n.bonds.grudge=0}s.pendingEventId=null;s.pendingDecision=null;stateOpenProposal("winter_share");s.pendingEventId=null;s.pendingDecision=null;window.__t=stateVoteTally();callStateVote()');assert.ok(run('__t.yes>=3'));assert.equal(run('s.stateCourt.proposalHistory[0].passed'),true);assert.equal(run('statePolicyActive("winter_share")'),true);assert.equal(run('s.stateCourt.currentProposal'),null);});

test('lobbying a hostile council member is one-shot and can improve their stance',()=>{const {run}=game();run(setup+'s.age=36;s.monthsRemaining=12;s.role="Boy Beyi";s.skills.speech=100;s.prestige=100;window.__circle=ensureStateCircle();window.__q=ensureStateCourt();__q.influence=90;__q.councilTrust=70;__q.tribeSupport=70;__q.rivalPressure=20;stateOpenProposal("caravan_guard");s.pendingEventId=null;s.pendingDecision=null;window.__p=currentStateProposal();window.__r=__circle.rival;__p.stances[__r.id]=-2;Math.random=()=>0;lobbyStateMember(__r.id)');assert.ok(run('__p.stances[__r.id]>=0'));assert.ok(run('__p.lobbiedIds.includes(__r.id)'));assert.ok(run('stateLobbyIssue(__r.id).includes("zaten")'));});

test('low-support council vote is rejected and records a cooldown instead of silently passing',()=>{const {run}=game();run(setup+'s.age=36;s.monthsRemaining=12;s.role="Boy Beyi";window.__circle=ensureStateCircle();window.__q=ensureStateCourt();__q.influence=55;__q.councilTrust=55;__q.tribeSupport=55;__q.rivalPressure=30;stateOpenProposal("craft_patronage");s.pendingEventId=null;s.pendingDecision=null;window.__p=currentStateProposal();for(const id of Object.keys(__p.stances))__p.stances[id]=-2;__q.influence=10;__q.councilTrust=10;__q.tribeSupport=10;__q.rivalPressure=90;callStateVote()');assert.equal(run('s.stateCourt.proposalHistory[0].passed'),false);assert.ok(run('s.stateCourt.failed>=1'));assert.ok(run('s.stateCourt.proposalCooldowns.craft_patronage>s.year+s.age'));assert.equal(run('statePolicyActive("craft_patronage")'),false);});

test('winter relief policy lowers food pressure and shortage over repeated quarters',()=>{const {run}=game();run(setup+'s.age=30;window.__q=ensureStateCourt();__q.activePolicies=[{id:"winter_share",name:STATE_PROPOSALS.winter_share.name,startedYear:s.year+s.age,expiresYear:s.year+s.age+2}];window.__e=ensureEconomy();__e.foodPressure=80;__e.shortageMonths=2;statePolicyQuarterTick(3);statePolicyQuarterTick(6)');assert.ok(run('__e.foodPressure<=74'));assert.ok(run('__e.shortageMonths<=1'));});

