test('workplace contacts stay unique and monthly peer-link tick tolerates duplicated legacy records',()=>{const {run}=game();run(setup+'s.age=30;s.role="Boy Beyi";ensureWorkplaceForRole(true);window.__w=ensureWorkplace();const p=currentWorkplaceContacts().find(x=>x.statusFlags?.workplacePosition==="peer");if(p)__w.contacts.push(p);window.__count=currentWorkplaceContacts().length;tickWorkplaceMonth({kind:"wait"})');assert.equal(run('currentWorkplaceContacts().length'),run('__count'));assert.ok(run('new Set(currentWorkplaceContacts().map(x=>x.id)).size===currentWorkplaceContacts().length'));});


test('v29 reputation system remains initialized in v30 fresh lives',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.ok(run('s.communityReputation&&Array.isArray(s.communityReputation.rumors)&&s.communityReputation.opinions'));assert.ok(run('Number.isFinite(s.communityReputation.honor)&&Number.isFinite(s.communityReputation.reliability)'));});

test('positive word starts from a real npc and spreads through the persistent social world',()=>{const {run}=game();run(setup+'s.age=30;window.__src=s.parents.find(n=>n.alive);window.__r=recordPublicWord("generosity",__src.name+" yardımını anlattı.",{generosity:4,honor:2},{severity:30,polarity:1,sourceId:__src.id,knownIds:[__src.id]});window.__before=__r.knownIds.length;Math.random=()=>0;tickCommunityReputationMonth(2);window.__new=__r.knownIds.find(id=>id!==__src.id)');assert.ok(run('__r.knownIds.length>__before'));assert.ok(run('!!npcById(__new)'));assert.ok(run('communityOpinion(npcById(__new),false).heard.includes(__r.id)'));});

test('false rumor can be countered publicly and partially restores heard opinions',()=>{const {run}=game();run(setup+'s.age=30;s.skills.speech=100;window.__rival=normalizeNPC({name:"Rakip",gender:"male",age:31,alive:true,type:"Rakip",rel:20,realm:s.realm,place:s.place},"Rakip");s.rivals=[__rival];window.__r=createCommunityRumor("false_rumor","Sözünde durmadığı söyleniyor.",{truth:false,polarity:-1,severity:36,sourceId:__rival.id,knownIds:[__rival.id]});window.__before=communityOpinion(__rival,false).score;Math.random=()=>0;reputationAction(__r.id,"answer")');assert.equal(run('__r.status'),"countered");assert.ok(run('communityOpinion(__rival,false).score>__before'));assert.equal(run('s.communityReputation.countered'),1);});

test('truthful damaging rumor can be repaired with restitution without erasing history',()=>{const {run}=game();run(setup+'s.age=30;s.wealth=100;window.__v=s.parents.find(n=>n.alive);window.__r=createCommunityRumor("crime","Zarar verdiğin konuşuluyor.",{truth:true,polarity:-1,severity:42,sourceId:__v.id,knownIds:[__v.id],caseId:"case_x"});window.__w=s.wealth;reputationAction(__r.id,"repair")');assert.equal(run('__r.status'),"repaired");assert.ok(run('s.wealth<__w'));assert.equal(run('s.communityReputation.repaired'),1);assert.ok(run('s.communityReputation.rumors.some(x=>x.id===__r.id)'));});

test('hidden crime with no witnesses creates no magical public bad reputation',()=>{const {run}=game();run(setup+'s.age=30;s.monthsRemaining=12;s.pendingEventId=null;s.pendingDecision=null;crimeWitnesses=()=>[];Math.random=()=>.99;window.__before=activeCommunityRumors(-1).length;commitCrime(D.crimes[0].id)');assert.equal(run('activeCommunityRumors(-1).length'),run('__before'));});

