test('v30 npc family conflicts survive heir continuation when both relatives remain in the graph',()=>{const {run}=game();run(setup+'s.age=60;while(s.siblings.filter(n=>n.alive).length<2){const g=s.siblings.length%2?"female":"male";s.siblings.push(normalizeNPC({name:"EskiKardes"+s.siblings.length,gender:g,age:40,alive:true,type:g==="male"?"Erkek kardeş":"Kız kardeş",rel:60,parentIds:s.parents.map(p=>p.id),realm:s.realm,place:s.place},g==="male"?"Erkek kardeş":"Kız kardeş"))}window.__x=s.siblings.filter(n=>n.alive)[0];window.__y=s.siblings.filter(n=>n.alive)[1];window.__fc=createFamilyConflict(__x,__y,"inheritance",{heat:57});window.__fid=__fc.id;window.__child=normalizeNPC({name:"Varis",gender:"male",age:25,alive:true,type:"Çocuk",rel:85,realm:s.realm,place:s.place,birthYear:s.year+s.age-25,parentIds:[s.id]},"Çocuk");s.children=[__child];die();continueAsHeir(0)');assert.ok(run('s.familyDynamics&&s.familyDynamics.conflicts.some(x=>x.id===__fid)'));assert.ok(run('activeFamilyConflicts().some(x=>x.id===__fid)'));});

