test('v31 child training report event targets only children with an active training record',()=>{const {run}=game();run(setup+'s.age=35;s.wealth=20;window.__a=normalizeNPC({name:"A",gender:"male",age:12,alive:true,type:"Çocuk",parentIds:[s.id],realm:s.realm,place:s.place},"Çocuk");window.__b=normalizeNPC({name:"B",gender:"female",age:12,alive:true,type:"Çocuk",parentIds:[s.id],realm:s.realm,place:s.place},"Çocuk");s.children=[__a,__b];childTrainingAction(0,"enroll","craft");s.pendingEventId=null;s.pendingDecision=null;window.__e=EVENT_DECK.find(x=>x.id==="child_training_report_v31");window.__sel=eventTargetSelections("childTrainingStudent",__e.id)');assert.equal(run('eventRequirementOK(__e)'),true);assert.ok(run('__sel.some(x=>x.target.id===__a.id)'));assert.equal(run('__sel.some(x=>x.target.id===__b.id)'),false);assert.ok(run('eventDisplayText(__e,{targetId:__a.id}).includes("Usta yanında zanaat")'));});

test('v31 training report choice changes the persistent progress profile of the named child',()=>{const {run}=game();run(setup+'s.age=35;s.wealth=20;window.__c=normalizeNPC({name:"Cocuk",gender:"male",age:12,alive:true,type:"Çocuk",parentIds:[s.id],realm:s.realm,place:s.place},"Çocuk");s.children=[__c];childTrainingAction(0,"enroll","craft");s.pendingEventId=null;s.pendingDecision=null;window.__t=childTrainingProfile(__c);window.__p=__t.progress;applyChildTrainingReportEvent(__c,0)');assert.ok(run('__t.progress>__p'));assert.ok(run('__t.history.some(x=>x.type==="report_event"&&x.choice===0)'));});

test('v30 saves migrate to v31 and gain child training containers with a dedicated backup',()=>{const {run,storage}=game();run(setup+'s.age=35;window.__c=normalizeNPC({name:"Cocuk",gender:"male",age:10,alive:true,type:"Çocuk",parentIds:[s.id],realm:s.realm,place:s.place},"Çocuk");s.children=[__c];ensureChildProfile(__c);s.version=30;delete s.parenting.children[__c.id].training;save();load()');assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.parenting.children[__c.id].training&&Array.isArray(s.parenting.children[__c.id].training.completed)'));});


