/* v40: independent real-capital traders and direct market transfers */
const v40Setup="s.age=30;s.wealth=250;s.health=100;s.skill=100;s.prestige=80;s.skills.trade=70;s.assets.push('caravan_share');s.monthsRemaining=12;s.pendingEventId=null;s.pendingDecision=null;s.military.active=false;s.captive=false;ensureEconomy();";
test('v40 new characters and trade rivals have safe accounts',()=>{const {run}=game();assert.equal(run('s.version'),50);run(setup+v40Setup+"window.__n=caravanEnsureRival('river');");assert.equal(run('ensureCaravanTrade().competition.river.inventory.length'),0);assert.equal(run('ensureCaravanTrade().competition.river.revenue'),0);});
test('v40 independent merchant uses actual cash to buy one good',()=>{const {run}=game();run(setup+v40Setup+"window.__n=caravanEnsureRival('river');window.__cash=__n.wealth;caravanRivalCycle(3);");assert.equal(run('ensureCaravanTrade().competition.river.bought'),1);assert.equal(run('caravanRivalUnits(ensureCaravanTrade().competition.river)'),1);assert.equal(run('__cash-__n.wealth'),run('ensureCaravanTrade().competition.river.expenses'));});
test('v40 no two market turns in one quarter',()=>{const {run}=game();run(setup+v40Setup+"window.__n=caravanEnsureRival('river');caravanRivalCycle(3);window.__cash=__n.wealth;caravanRivalCycle(3);");assert.equal(run('ensureCaravanTrade().competition.river.cycles'),1);assert.equal(run('__n.wealth'),run('__cash'));});
test('v40 merchant sells actual stock and retains margin',()=>{const {run}=game();run(setup+v40Setup+"window.__n=caravanEnsureRival('steppe');window.__r=ensureCaravanTrade().competition.steppe;__r.inventory=[{goodId:'salt',qty:1,unitCost:3}];window.__cash=__n.wealth;caravanRivalCycle(3);");assert.equal(run('__r.sold'),1);assert.equal(run('__r.profit'),run('__r.revenue-3'));assert.equal(run('__n.wealth'),run('__cash+__r.revenue-__r.expenses'));});
test('v40 bankrupt merchant cannot fabricate cash or goods',()=>{const {run}=game();run(setup+v40Setup+"window.__n=caravanEnsureRival('river');__n.wealth=0;caravanRivalCycle(3);");assert.equal(run('ensureCaravanTrade().competition.river.stalls'),1);assert.equal(run('ensureCaravanTrade().competition.river.bought'),0);assert.equal(run('__n.wealth'),0);});
test('v40 real NPC sale creates temporary market supply competition',()=>{const {run}=game();run(setup+v40Setup+"caravanEnsureRival('river');window.__r=ensureCaravanTrade().competition.river;__r.heat=0;window.__base=caravanQuote('river').silk;__r.recentVolume=5;__r.lastSaleSerial=lifeSerial();window.__current=caravanQuote('river').silk;");assert.ok(run('__current<__base'));});
test('v40 market wholesale requires goods and NPC solvency',()=>{const {run}=game();run(setup+v40Setup+"window.__n=caravanEnsureRival('river');window.__out=caravanWholesaleIssue('salt');window.__t=ensureCaravanTrade();__t.stage='market';__t.routeId='river';__t.cargo=[{goodId:'salt',qty:1,unitCost:2}];__t.prices.salt=12;__n.wealth=0;window.__poor=caravanWholesaleIssue('salt');");assert.ok(run('__out.includes("pazarda")'));assert.ok(run('__poor.includes("nakdi")'));});
test('v40 wholesale transfers exactly one good and price from NPC wallet',()=>{const {run}=game();run(setup+v40Setup+"window.__n=caravanEnsureRival('river');window.__t=ensureCaravanTrade();__t.stage='market';__t.routeId='river';__t.cargo=[{goodId:'salt',qty:2,unitCost:2}];__t.prices.salt=12;__t.trip={routeId:'river',spent:4,earned:0,fee:0};__n.wealth=100;s.monthsRemaining=9;window.__cash=s.wealth;window.__npc=__n.wealth;window.__price=caravanWholesalePrice('salt');window.__done=caravanWholesaleAction('salt');");assert.equal(run('__done'),true);assert.equal(run('s.wealth'),run('__cash+__price'));assert.equal(run('__n.wealth'),run('__npc-__price'));assert.equal(run('ensureCaravanTrade().cargo[0].qty'),1);assert.equal(run('caravanRivalUnits(ensureCaravanTrade().competition.river)'),1);});
test('v40 spent cargo cannot be sold twice to merchant',()=>{const {run}=game();run(setup+v40Setup+"window.__n=caravanEnsureRival('river');window.__t=ensureCaravanTrade();__t.stage='market';__t.routeId='river';__t.cargo=[{goodId:'salt',qty:1,unitCost:2}];__t.prices.salt=12;__n.wealth=100;s.monthsRemaining=9;caravanWholesaleAction('salt');window.__issue=caravanWholesaleIssue('salt');");assert.ok(run('__issue.includes("stok yok")'));assert.equal(run('ensureCaravanTrade().competition.river.bought'),1);});
test('v40 main market sales displace rival customers next quarter',()=>{const {run}=game();run(setup+v40Setup+"caravanEnsureRival('river');window.__t=ensureCaravanTrade();__t.stage='market';__t.routeId='river';__t.cargo=[{goodId:'salt',qty:3,unitCost:3}];__t.trip={routeId:'river',spent:9,earned:0,fee:0};__t.prices.salt=9;s.monthsRemaining=9;window.__ok=caravanAction('sell');");assert.equal(run('__ok'),true);assert.equal(run('ensureCaravanTrade().competition.river.displaced'),2);});
test('v40 inflated or invalid inventories are bounded and cleaned',()=>{const {run}=game();run(setup+v40Setup+"caravanEnsureRival('river');window.__r=ensureCaravanTrade().competition.river;__r.inventory=Array.from({length:100},()=>({goodId:'salt',qty:99,unitCost:3}));__r.ledger=Array.from({length:100},()=>({kind:'x'}));ensureCaravanTrade();");assert.ok(run('caravanRivalUnits(ensureCaravanTrade().competition.river)<=8'));assert.ok(run('ensureCaravanTrade().competition.river.ledger.length<=30'));});
test('v40 old v39 saves migrate to version 40 and keep rival identity',()=>{const {run,storage}=game();run(setup+v40Setup+"window.__n=caravanEnsureRival('river');window.__id=__n.id;s.version=39;delete s.caravanTrade.competition.river.inventory;save();load();");assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v40'));assert.equal(run('ensureCaravanTrade().competition.river.npcId'),run('__id'));});
test('v40 heirs carry their actual rival NPC record instead of orphan IDs',()=>{const {run}=game();run(setup+v40Setup+"window.__n=caravanEnsureRival('mountain');window.__inherit=caravanInheritance(s,{assets:['caravan_share']});");assert.equal(run('__inherit.inheritedRivals[0].id'),run('__n.id'));assert.equal(run('caravanInheritance(s,{assets:[]})'),null);});


/* v41 — Regional markets, real supply, price shocks, recovery, migration. */
const v41Ready="s.age=30;s.wealth=250;s.health=100;s.skill=100;s.prestige=80;s.skills.trade=70;s.assets.push('caravan_share');s.monthsRemaining=9;s.pendingEventId=null;s.pendingDecision=null;s.military.active=false;s.captive=false;ensureEconomy();";
test('v41 fresh life has three four-good regional markets',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.equal(run('Object.keys(ensureCaravanTrade().markets).length'),3);assert.equal(run('Object.keys(caravanMarketState("river").goods).length'),4);});
test('v41 scarcity raises only target regional price',()=>{const {run}=game();run(setup+v41Ready+"window.__p=caravanQuote('mountain').iron;window.__other=caravanQuote('river').iron;window.__ok=caravanMarketShock('mountain','iron','shortage');");assert.equal(run('__ok'),true);assert.ok(run('caravanQuote("mountain").iron>__p'));assert.equal(run('caravanQuote("river").iron'),run('__other'));});
test('v41 surplus depresses targeted product but not other goods',()=>{const {run}=game();run(setup+v41Ready+"window.__p=caravanMarketMultiplier('steppe','silk');window.__other=caravanMarketMultiplier('steppe','salt');caravanMarketShock('steppe','silk','surplus');");assert.ok(run('caravanMarketMultiplier("steppe","silk")<__p'));assert.equal(run('caravanMarketMultiplier("steppe","salt")'),run('__other'));});
test('v41 an ongoing crisis prevents stacking another',()=>{const {run}=game();run(setup+v41Ready+"window.__a=caravanMarketShock('river','wool','shortage');window.__b=caravanMarketShock('river','wool','shortage');");assert.equal(run('__a'),true);assert.equal(run('__b'),false);assert.equal(run('caravanMarketState("river").goods.wool.supply'),5);});
test('v41 sold player goods enter only actual destination market',()=>{const {run}=game();run(setup+v41Ready+"window.__t=ensureCaravanTrade();__t.stage='market';__t.routeId='river';__t.cargo=[{goodId:'wool',qty:2,unitCost:4},{goodId:'salt',qty:1,unitCost:3}];__t.prices.wool=8;__t.prices.salt=5;__t.trip={routeId:'river',spent:11,earned:0,fee:0};window.__ok=caravanAction('sell');");assert.equal(run('__ok'),true);assert.equal(run('caravanMarketState("river").goods.wool.supply'),12);assert.equal(run('caravanMarketState("river").goods.salt.supply'),11);assert.equal(run('caravanMarketState("mountain").goods.wool.supply'),10);});
test('v41 already sold inventory cannot inflate market twice',()=>{const {run}=game();run(setup+v41Ready+"window.__t=ensureCaravanTrade();__t.stage='market';__t.routeId='river';__t.cargo=[{goodId:'silk',qty:1,unitCost:3}];__t.prices.silk=15;caravanAction('sell');window.__stock=caravanMarketState('river').goods.silk.supply;window.__issue=caravanIssue('sell');");assert.ok(run('__issue.includes("yük")'));assert.equal(run('caravanMarketState("river").goods.silk.supply'),run('__stock'));});
test('v41 autonomous rival purchase actually reduces local market supply',()=>{const {run}=game();run(setup+v41Ready+"caravanEnsureRival('mountain');Math.random=()=>.99;caravanRivalCycle(3);window.__id=ensureCaravanTrade().competition.mountain.inventory[0].goodId;");assert.equal(run('caravanMarketState("mountain").goods[__id].supply'),9);assert.equal(run('caravanMarketState("river").goods[__id].supply'),10);});
test('v41 autonomous sale increases local supply when next purchase is different good',()=>{const {run}=game();run(setup+v41Ready+"window.__n=caravanEnsureRival('river');window.__rec=ensureCaravanTrade().competition.river;__rec.inventory=[{goodId:'iron',qty:1,unitCost:4}];Math.random=()=>.99;caravanRivalCycle(3);");assert.equal(run('caravanMarketState("river").goods.iron.supply'),11);assert.equal(run('ensureCaravanTrade().competition.river.sold'),1);});
test('v41 a wholesale transfer to NPC is not counted as public market supply',()=>{const {run}=game();run(setup+v41Ready+"window.__n=caravanEnsureRival('river');window.__t=ensureCaravanTrade();__t.stage='market';__t.routeId='river';__t.cargo=[{goodId:'salt',qty:1,unitCost:3}];__t.prices.salt=13;__n.wealth=100;window.__s=caravanMarketState('river').goods.salt.supply;window.__ok=caravanWholesaleAction('salt');");assert.equal(run('__ok'),true);assert.equal(run('caravanMarketState("river").goods.salt.supply'),run('__s'));assert.equal(run('caravanRivalUnits(ensureCaravanTrade().competition.river)'),1);});
test('v41 quarterly recovery restores one unit of scarcity and demand',()=>{const {run}=game();run(setup+v41Ready+"caravanMarketShock('river','salt','shortage');window.__s=caravanMarketState('river').goods.salt.supply;window.__d=caravanMarketState('river').goods.salt.demand;Math.random=()=>.99;caravanMarketQuarterTick(3);");assert.equal(run('caravanMarketState("river").goods.salt.supply'),run('__s+1'));assert.equal(run('caravanMarketState("river").goods.salt.demand'),run('__d-1'));assert.equal(run('caravanMarketState("river").crisis.remaining'),2);});
test('v41 same quarterly period cannot trigger market recovery twice',()=>{const {run}=game();run(setup+v41Ready+"caravanMarketShock('river','silk','surplus');Math.random=()=>.99;caravanMarketQuarterTick(3);window.__s=caravanMarketState('river').goods.silk.supply;window.__q=caravanMarketState('river').quarters;caravanMarketQuarterTick(3);");assert.equal(run('caravanMarketState("river").goods.silk.supply'),run('__s'));assert.equal(run('caravanMarketState("river").quarters'),run('__q'));});
test('v41 finite crisis ends after three distinct quarterly periods',()=>{const {run}=game();run(setup+v41Ready+"caravanMarketShock('river','iron','shortage');Math.random=()=>.99;for(let i=0;i<3;i++){s.monthsRemaining=9-i*3;caravanMarketQuarterTick(3);}");assert.equal(run('caravanMarketState("river").crisis'),null);assert.ok(run('caravanMarketState("river").goods.iron.supply>5'));});
test('v41 price locked at departure is not repriced by a later crisis',()=>{const {run}=game();run(setup+v41Ready+"window.__t=ensureCaravanTrade();__t.cargo=[{goodId:'iron',qty:2,unitCost:4}];Math.random=()=>.99;window.__go=caravanAction('depart','mountain');window.__locked=ensureCaravanTrade().prices.iron;caravanMarketShock('mountain','iron','shortage');");assert.equal(run('__go'),true);assert.equal(run('ensureCaravanTrade().prices.iron'),run('__locked'));assert.ok(run('caravanQuote("mountain").iron>=__locked'));});
test('v41 save and load preserve recorded shortages, supply and journaling',()=>{const {run}=game();run(setup+v41Ready+"caravanMarketShock('steppe','silk','surplus');caravanMarketExchange('steppe','salt',4,'playerSell');window.__q=caravanMarketState('steppe').goods.salt.supply;save();load();");assert.equal(run('caravanMarketState("steppe").crisis.kind'),'surplus');assert.equal(run('caravanMarketState("steppe").goods.salt.supply'),run('__q'));assert.ok(run('caravanMarketState("steppe").history.length>=2'));});
test('v41 invalid stored market fields are safely bounded',()=>{const {run}=game();run(setup+v41Ready+"window.__m=caravanMarketState('river');__m.goods.iron.supply=-500;__m.goods.iron.demand=500;__m.crisis={kind:'bad',goodId:'iron',remaining:200};__m.history=Array.from({length:100},()=>({kind:'fake'}));ensureCaravanTrade();");assert.equal(run('caravanMarketState("river").goods.iron.supply'),0);assert.equal(run('caravanMarketState("river").goods.iron.demand'),24);assert.equal(run('caravanMarketState("river").crisis'),null);assert.equal(run('caravanMarketState("river").history.length'),36);});
test('v41 v40 save migration backs up and preserves old cargo',()=>{const {run,storage}=game();run(setup+v41Ready+"ensureCaravanTrade().cargo=[{goodId:'salt',qty:2,unitCost:4}];s.version=40;delete s.caravanTrade.markets;save();load();");assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v41'));assert.equal(run('ensureCaravanTrade().cargo[0].qty'),2);assert.equal(run('caravanMarketState("river").goods.salt.supply'),10);});
test('v41 inheriting caravan shares carries real market scarcity',()=>{const {run}=game();run(setup+v41Ready+"caravanMarketShock('mountain','wool','shortage');window.__yes=caravanInheritance(s,{assets:['caravan_share']});window.__no=caravanInheritance(s,{assets:[]});");assert.equal(run('__yes.markets.mountain.crisis.kind'),'shortage');assert.equal(run('__no'),null);});
test('v41 regional market UI shows actual commodity status and crisis',()=>{const {run}=game();run(setup+v41Ready+"caravanMarketShock('river','iron','shortage');window.__html=caravanMarketSummaryHtml();");assert.ok(run('__html.includes("Bölgesel Pazarlar")'));assert.ok(run('__html.includes("Ticaret kıtlığı")'));assert.ok(run('__html.includes("arz")'));});


/* v42: fixed-funding delivery contracts, due dates, inventory and inheritance */
const v42F="s.age=30;s.wealth=350;s.health=100;s.skill=100;s.prestige=80;s.skills.trade=70;s.assets.push('caravan_share');s.monthsRemaining=9;s.pendingEventId=null;s.pendingDecision=null;s.military.active=false;s.captive=false;ensureEconomy();";
const v42S="window.__ok=caravanContractAction('seek');s.pendingEventId=null;s.pendingDecision=null;window.__q=ensureCaravanTrade().contracts.offers[0];";
const v42A=v42S+"window.__n=npcById(__q.issuerId);window.__before=__n.wealth;window.__accepted=caravanContractAction('accept',__q.id);s.pendingEventId=null;s.pendingDecision=null;";
const v42M="window.__t=ensureCaravanTrade();__t.stage='market';__t.routeId=__q.routeId;__t.cargo=[{goodId:__q.goodId,qty:__q.qty,unitCost:2}];s.monthsRemaining=9;";
test('v42 new life has empty delivery contract registry',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.equal(run('ensureCaravanTrade().contracts.active'),null);assert.equal(run('ensureCaravanTrade().contracts.fulfilled'),0);});
test('v42 adult and caravan ownership are required',()=>{const {run}=game();run(setup+"window.__no=caravanContractIssue('seek');s.assets.push('caravan_share');s.age=16;window.__minor=caravanContractIssue('seek');");assert.ok(run('__no.includes("Kervan Payı")'));assert.ok(run('__minor.includes("18")'));});
test('v42 seeking uses real funded NPCs without awarding free stock',()=>{const {run}=game();run(setup+v42F+v42S);assert.equal(run('__ok'),true);assert.ok(run('ensureCaravanTrade().contracts.offers.length>0'));assert.ok(run('npcById(__q.issuerId).alive'));assert.equal(run('caravanCargoWeight()'),0);});
test('v42 searching again before six months is blocked',()=>{const {run}=game();run(setup+v42F+v42S);assert.ok(run('caravanContractIssue("seek").includes("altı ay")'));});
test('v42 accepting reserves actual issuer wealth once',()=>{const {run}=game();run(setup+v42F+v42A);assert.equal(run('__accepted'),true);assert.equal(run('__n.wealth'),run('__before-__q.reward'));assert.equal(run('ensureCaravanTrade().contracts.offers.length'),0);assert.ok(run('caravanContractIssue("accept",__q.id).includes("bir")'));});
test('v42 broke issuer cannot fund a new agreement',()=>{const {run}=game();run(setup+v42F+v42S+"window.__n=npcById(__q.issuerId);__n.wealth=0;window.__why=caravanContractIssue('accept',__q.id);");assert.ok(run('__why.includes("serveti")'));assert.equal(run('ensureCaravanTrade().contracts.active'),null);});
test('v42 contractual due date accounts for destination route',()=>{const {run}=game();run(setup+v42F+v42A);assert.equal(run('ensureCaravanTrade().contracts.active.deadlineSerial-ensureCaravanTrade().contracts.active.acceptedSerial'),run('CARAVAN_ROUTES[__q.routeId].months+8'));});
test('v42 wrong destination and absent cargo block completion',()=>{const {run}=game();run(setup+v42F+v42A+"window.__t=ensureCaravanTrade();__t.stage='market';__t.routeId=Object.keys(CARAVAN_ROUTES).find(x=>x!==__q.routeId);window.__wrong=caravanContractIssue('deliver',__q.id);__t.routeId=__q.routeId;window.__empty=caravanContractIssue('deliver',__q.id);");assert.ok(run('__wrong.includes("varış")'));assert.ok(run('__empty.includes("gerçek")'));});
test('v42 finished delivery transfers real inventory and escrow exactly once',()=>{const {run}=game();run(setup+v42F+v42A+v42M+"window.__p=s.wealth;window.__r=__t.competition[__q.routeId];window.__units=caravanRivalUnits(__r);window.__done=caravanContractAction('deliver',__q.id);window.__again=caravanContractIssue('deliver',__q.id);");assert.equal(run('__done'),true);assert.equal(run('s.wealth'),run('__p+__q.reward'));assert.equal(run('__n.wealth'),run('__before-__q.reward'));assert.equal(run('ensureCaravanTrade().cargo.length'),0);assert.equal(run('caravanRivalUnits(__r)'),run('__units+__q.qty'));assert.equal(run('ensureCaravanTrade().contracts.fulfilled'),1);assert.ok(run('__again.includes("Etkin")'));});
test('v42 FIFO delivery keeps leftover cargo',()=>{const {run}=game();run(setup+v42F+v42A+v42M+"__t.cargo=[{goodId:__q.goodId,qty:1,unitCost:2},{goodId:__q.goodId,qty:__q.qty,unitCost:3},{goodId:__q.goodId==='salt'?'wool':'salt',qty:1,unitCost:7}];caravanContractAction('deliver',__q.id);");assert.equal(run('ensureCaravanTrade().cargo.filter(x=>x.goodId===__q.goodId).reduce((n,x)=>n+x.qty,0)'),1);assert.equal(run('ensureCaravanTrade().cargo.length'),2);});
test('v42 expired promise refunds escrow and penalizes exactly once',()=>{const {run}=game();run(setup+v42F+v42A+"window.__p=s.wealth;window.__r=s.prestige;ensureCaravanTrade().contracts.active.deadlineSerial=lifeSerial()-1;caravanContractMonthTick();window.__once=s.wealth;caravanContractMonthTick();");assert.equal(run('__n.wealth'),run('__before'));assert.equal(run('ensureCaravanTrade().contracts.failed'),1);assert.equal(run('s.prestige'),run('__r-4'));assert.equal(run('s.wealth'),run('__p-2'));assert.equal(run('s.wealth'),run('__once'));});
test('v42 buyer death voids the promise without penalty',()=>{const {run}=game();run(setup+v42F+v42A+"window.__r=s.prestige;__n.alive=false;caravanContractMonthTick();");assert.equal(run('ensureCaravanTrade().contracts.active'),null);assert.equal(run('s.prestige'),run('__r'));assert.equal(run('__n.wealth'),run('__before'));assert.equal(run('ensureCaravanTrade().contracts.history[0].status'),'void');});
test('v42 reserved NPC storage prevents competing autonomous overfill',()=>{const {run}=game();run(setup+v42F+v42A+"window.__r=ensureCaravanTrade().competition[__q.routeId];__r.inventory=[{goodId:'salt',qty:8-__q.qty,unitCost:2}];Math.random=()=>.99;caravanRivalCycle(3);");assert.ok(run('caravanRivalUnits(__r)<=8-__q.qty'));});
test('v42 active agreement prevents selling caravan asset',()=>{const {run}=game();run(setup+v42F+v42A+"window.__why=accessIssue({kind:'asset',id:'caravan_share',sell:true});");assert.ok(run('__why.includes("kervanı")'));});
test('v42 expired proposal removes only itself and preserves valid offers',()=>{const {run}=game();run(setup+v42F+v42S+"window.__p=s.prestige;window.__count=ensureCaravanTrade().contracts.offers.length;ensureCaravanTrade().contracts.offers[0].validUntil=lifeSerial()-1;caravanContractMonthTick();");assert.equal(run('ensureCaravanTrade().contracts.offers.length'),run('__count-1'));assert.equal(run('s.prestige'),run('__p'));});
test('v42 active contract and time limit persist on reloading save',()=>{const {run}=game();run(setup+v42F+v42A+"window.__time=ensureCaravanTrade().contracts.active.deadlineSerial;save();load();");assert.equal(run('ensureCaravanTrade().contracts.active.id'),run('__q.id'));assert.equal(run('ensureCaravanTrade().contracts.active.deadlineSerial'),run('__time'));});
test('v42 heirs carry contract history but cannot inherit active obligation',()=>{const {run}=game();run(setup+v42F+v42A+"window.__inherited=caravanInheritance(s,{assets:['caravan_share']});");assert.equal(run('__inherited.contracts.active'),null);assert.equal(run('__inherited.contracts.offers.length'),0);assert.equal(run('caravanInheritance(s,{assets:[]})'),null);});
test('v42 migration from v41 backs up without inventing offers',()=>{const {run,storage}=game();run(setup+v42F+"s.version=41;delete s.caravanTrade.contracts;save();load();");assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v42'));assert.equal(run('ensureCaravanTrade().contracts.active'),null);});
test('v42 corrupted contract data is filtered safely',()=>{const {run}=game();run(setup+v42F+"window.__t=ensureCaravanTrade();__t.contracts.active={id:'fake',routeId:'bad',goodId:'silk',qty:999,reward:999,deadlineSerial:5};__t.contracts.offers=[{id:'bad',routeId:'bad',goodId:'salt',reward:5,qty:1}];ensureCaravanTrade();");assert.equal(run('ensureCaravanTrade().contracts.active'),null);assert.equal(run('ensureCaravanTrade().contracts.offers.length'),0);});
test('v42 delivery screen shows real reward and offers',()=>{const {run}=game();run(setup+v42F+v42S+"window.__view=caravanContractSummaryHtml();");assert.ok(run('__view.includes("Ticaret Sözleşmeleri")'));assert.ok(run('__view.includes("Sözleşmeyi kabul et")'));});


/* v43: regional merchant guilds, earned reputation, paid membership and time-bound perks */
const v43F="s.age=30;s.wealth=350;s.health=100;s.skill=100;s.prestige=80;s.skills.trade=70;s.assets.push('caravan_share');s.monthsRemaining=9;s.pendingEventId=null;s.pendingDecision=null;s.military.active=false;s.captive=false;ensureEconomy();";
const v43Setup=v43F+"caravanEnsureRival('river');caravanEnsureRival('mountain');caravanEnsureRival('steppe');";
const v43Eligible=v43Setup+"ensureCaravanTrade().contracts.fulfilled=2;ensureCaravanTrade().guild.reputation=24;";
const v43Member=v43Eligible+"window.__sponsor=npcById(ensureCaravanTrade().competition.river.npcId);window.__joined=caravanGuildAction('join','river');s.pendingEventId=null;s.pendingDecision=null;";
test('v43 fresh game creates harmless empty guild and ranks',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.equal(run('ensureCaravanTrade().guild.reputation'),0);assert.equal(run('ensureCaravanTrade().guild.routeId'),null);assert.equal(run('caravanGuildRank()'),'Çırak Tüccar');});
test('v43 guild membership requires real owner and adult age',()=>{const {run}=game();run(setup+"window.__no=caravanGuildIssue('join','river');s.assets.push('caravan_share');s.age=15;window.__young=caravanGuildIssue('join','river');");assert.ok(run('__no.includes("Kervan Payı")'));assert.ok(run('__young.includes("18")'));});
test('v43 no honorary guild without two completed paid deliveries',()=>{const {run}=game();run(setup+v43Setup+"window.__before=caravanGuildIssue('join','river');ensureCaravanTrade().guild.reputation=24;window.__still=caravanGuildIssue('join','river');");assert.ok(run('__before.includes("iki")'));assert.ok(run('__still.includes("iki")'));});
test('v43 sponsor must be actual live NPC present at requested regional market',()=>{const {run}=game();run(setup+v43Eligible+"window.__n=npcById(ensureCaravanTrade().competition.river.npcId);__n.alive=false;window.__why=caravanGuildIssue('join','river');");assert.ok(run('__why.includes("tüccar")'));});
test('v43 joining guild costs player eight and rewards sponsor exactly eight',()=>{const {run}=game();run(setup+v43Eligible+"window.__n=npcById(ensureCaravanTrade().competition.river.npcId);window.__cash=s.wealth;window.__npcCash=__n.wealth;window.__ok=caravanGuildAction('join','river');");assert.equal(run('__ok'),true);assert.equal(run('s.wealth'),run('__cash-8'));assert.equal(run('__n.wealth'),run('__npcCash+8'));assert.equal(run('ensureCaravanTrade().guild.sponsorId'),run('__n.id'));});
test('v43 guild dues cannot overdraw poor player and cannot be collected twice',()=>{const {run}=game();run(setup+v43Eligible+"s.wealth=7;window.__poor=caravanGuildIssue('join','river');s.wealth=200;caravanGuildAction('join','river');s.pendingEventId=null;s.pendingDecision=null;window.__duplicate=caravanGuildIssue('join','river');");assert.ok(run('__poor.includes("8")'));assert.ok(run('__duplicate.includes("Önce")'));});
test('v43 membership only benefits its own regional route',()=>{const {run}=game();run(setup+v43Member);assert.equal(run('__joined'),true);assert.equal(run('caravanGuildBenefit("river")'),true);assert.equal(run('caravanGuildBenefit("mountain")'),false);assert.equal(run('caravanGuildBenefit("steppe")'),false);});
test('v43 guild route reduces real departure toll by one',()=>{const {run}=game();run(setup+v43Member+"window.__t=ensureCaravanTrade();__t.cargo=[{goodId:'salt',qty:1,unitCost:2}];s.monthsRemaining=9;window.__cash=s.wealth;Math.random=()=>.99;window.__go=caravanAction('depart','river');");assert.equal(run('__go'),true);assert.equal(run('ensureCaravanTrade().trip.fee'),1);assert.equal(run('s.wealth'),run('__cash-1'));});
test('v43 foreign routes retain original fees even for guild member',()=>{const {run}=game();run(setup+v43Member+"window.__t=ensureCaravanTrade();__t.cargo=[{goodId:'salt',qty:1,unitCost:2}];s.monthsRemaining=9;Math.random=()=>.99;caravanAction('depart','mountain');");assert.equal(run('ensureCaravanTrade().trip.fee'),4);});
test('v43 guild contract offer in own market improves reward with existing NPC funding',()=>{const {run}=game();run(setup+v43Member+"window.__n=npcById(ensureCaravanTrade().competition.river.npcId);__n.wealth=1000;window.__ok=caravanContractAction('seek');window.__offer=ensureCaravanTrade().contracts.offers.find(x=>x.routeId==='river');window.__price=caravanQuote('river')[__offer.goodId];");assert.equal(run('__ok'),true);assert.ok(run('__offer.guildBonus'));assert.ok(run('__offer.reward>__offer.qty*(__price+3)'));assert.ok(run('__n.wealth>=__offer.reward'));});
test('v43 privileged offer still cannot exceed NPC ability to pay',()=>{const {run}=game();run(setup+v43Member+"window.__n=npcById(ensureCaravanTrade().competition.river.npcId);__n.wealth=1;caravanContractAction('seek');");assert.equal(run('ensureCaravanTrade().contracts.offers.filter(x=>x.routeId==="river").length'),0);});
test('v43 guild privilege does not leak to unrelated contract offers',()=>{const {run}=game();run(setup+v43Member+"caravanContractAction('seek');window.__different=ensureCaravanTrade().contracts.offers.filter(x=>x.routeId!=='river');");assert.ok(run('__different.length>0'));assert.ok(run('__different.every(x=>!x.guildBonus)'));});
test('v43 fulfilled actual contract increases reputation once',()=>{const {run}=game();run(setup+v43Setup+"window.__q={id:'v43-test',routeId:'river',issuerId:ensureCaravanTrade().competition.river.npcId,goodId:'salt',qty:1,reward:8,deadlineSerial:lifeSerial()+5};ensureCaravanTrade().contracts.active=__q;caravanContractFinish('fulfilled','test');caravanContractFinish('fulfilled','repeat');");assert.equal(run('ensureCaravanTrade().guild.reputation'),12);assert.equal(run('ensureCaravanTrade().contracts.fulfilled'),1);});
test('v43 expired actual contract loses reputation once and respects zero floor',()=>{const {run}=game();run(setup+v43Setup+"window.__c=ensureCaravanTrade().contracts;__c.guild=undefined;ensureCaravanTrade().guild.reputation=6;__c.active={id:'bad',routeId:'river',issuerId:__c?ensureCaravanTrade().competition.river.npcId:null,goodId:'salt',qty:1,reward:8,deadlineSerial:lifeSerial()-1};caravanContractFinish('expired','late');caravanContractFinish('expired','twice');");assert.equal(run('ensureCaravanTrade().guild.reputation'),0);assert.equal(run('ensureCaravanTrade().contracts.failed'),1);});
test('v43 guild rank promotes at exact 24 and 60 thresholds',()=>{const {run}=game();run(setup+v43Setup+"ensureCaravanTrade().guild.reputation=23;window.__low=caravanGuildRank();ensureCaravanTrade().guild.reputation=24;window.__mid=caravanGuildRank();ensureCaravanTrade().guild.reputation=60;window.__high=caravanGuildRank();");assert.equal(run('__low'),'Çırak Tüccar');assert.equal(run('__mid'),'Güvenilir Tüccar');assert.equal(run('__high'),'Usta Tüccar');});
test('v43 maximum reputation stays clamped to 100',()=>{const {run}=game();run(setup+v43Setup+"ensureCaravanTrade().guild.reputation=99;caravanGuildReputationChange(12,'fulfilled',{id:'x',routeId:'river'});");assert.equal(run('ensureCaravanTrade().guild.reputation'),100);});
test('v43 leaving guild removes benefits without refunding entrance fee',()=>{const {run}=game();run(setup+v43Member+"window.__cash=s.wealth;window.__done=caravanGuildAction('leave','river');");assert.equal(run('__done'),true);assert.equal(run('caravanGuildBenefit("river")'),false);assert.equal(run('s.wealth'),run('__cash'));assert.equal(run('ensureCaravanTrade().guild.history[0].kind'),'leave');});
test('v43 guild membership survives browser save and load',()=>{const {run}=game();run(setup+v43Member+"window.__npc=ensureCaravanTrade().guild.sponsorId;save();load();");assert.equal(run('ensureCaravanTrade().guild.routeId'),'river');assert.equal(run('ensureCaravanTrade().guild.sponsorId'),run('__npc'));assert.equal(run('ensureCaravanTrade().guild.reputation'),24);});
test('v43 heir retains records but cannot impersonate prior merchant guild member',()=>{const {run}=game();run(setup+v43Member+"window.__saved=caravanInheritance(s,{assets:['caravan_share']});");assert.equal(run('__saved.guild.routeId'),null);assert.equal(run('__saved.guild.reputation'),0);assert.equal(run('__saved.guild.history.some(x=>x.kind==="join")'),true);});
test('v43 corrupted guild fields are normalized and invalid region removed',()=>{const {run}=game();run(setup+v43Setup+"window.__g=ensureCaravanTrade().guild;__g.routeId='forgotten';__g.reputation=999;__g.history=Array.from({length:100},()=>({kind:'fake'}));ensureCaravanTrade();");assert.equal(run('ensureCaravanTrade().guild.routeId'),null);assert.equal(run('ensureCaravanTrade().guild.reputation'),100);assert.equal(run('ensureCaravanTrade().guild.history.length'),40);});
test('v43 migrating v42 save creates backup and initializes guild',()=>{const {run,storage}=game();run(setup+v43Setup+"s.version=42;delete s.caravanTrade.guild;save();load();");assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v43'));assert.equal(run('ensureCaravanTrade().guild.routeId'),null);});
test('v43 guild UI shows reputation and sponsor identity',()=>{const {run}=game();run(setup+v43Member+"window.__html=caravanGuildSummaryHtml();");assert.ok(run('__html.includes("Tüccar İtibarı")'));assert.ok(run('__html.includes("24/100")'));assert.ok(run('__html.includes(__sponsor.name)'));});


/* v44 — genuinely-funded guild power, regional councils and bounded decrees */
const v44Fixture="s.age=30;s.wealth=350;s.health=100;s.skill=100;s.prestige=80;s.skills.trade=70;s.assets.push('caravan_share');s.monthsRemaining=9;s.pendingEventId=null;s.pendingDecision=null;s.military.active=false;s.captive=false;ensureEconomy();";
const v44Member=v44Fixture+"window.__n=caravanEnsureRival('river');window.__t=ensureCaravanTrade();__t.guild.routeId='river';__t.guild.sponsorId=__n.id;__t.guild.reputation=60;__t.contracts.fulfilled=3;";
test('v44 fresh save has 3 neutral separate political councils',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.equal(run('Object.keys(ensureCaravanTrade().guild.politics).length'),3);assert.equal(run('caravanPoliticsRecord("river").influence'),0);assert.equal(run('caravanPoliticsRecord("river").rivalStrength'),12);});
test('v44 only adults with caravan shares can hold political talks',()=>{const {run}=game();run(setup+"window.__no=caravanPoliticsIssue('lobby','river');s.assets.push('caravan_share');s.age=16;window.__minor=caravanPoliticsIssue('lobby','river');");assert.ok(run('__no.includes("yetişkin")'));assert.ok(run('__minor.includes("yetişkin")'));});
test('v44 unaffiliated guild member cannot lobby in another region',()=>{const {run}=game();run(setup+v44Member+"window.__why=caravanPoliticsIssue('lobby','mountain');");assert.ok(run('__why.includes("üyesi")'));});
test('v44 lobbying transfers exactly four from player to NPC, raising influence',()=>{const {run}=game();run(setup+v44Member+"window.__pc=s.wealth;window.__nc=__n.wealth;window.__ok=caravanPoliticsAction('lobby','river');");assert.equal(run('__ok'),true);assert.equal(run('s.wealth'),run('__pc-4'));assert.equal(run('__n.wealth'),run('__nc+4'));assert.equal(run('caravanPoliticsRecord("river").influence'),15);});
test('v44 duplicate six-month influence lobbying is blocked',()=>{const {run}=game();run(setup+v44Member+"caravanPoliticsAction('lobby','river');window.__issue=caravanPoliticsIssue('lobby','river');");assert.ok(run('__issue.includes("altı ay")'));});
test('v44 council contribution blocked without sufficient cash or live sponsor',()=>{const {run}=game();run(setup+v44Member+"s.wealth=3;window.__poor=caravanPoliticsIssue('lobby','river');s.wealth=350;__n.alive=false;window.__dead=caravanPoliticsIssue('lobby','river');");assert.ok(run('__poor.includes("4 servet")'));assert.ok(run('__dead.includes("temsilcisi")'));});
test('v44 decree requires higher influence than real rival political strength',()=>{const {run}=game();run(setup+v44Member+"window.__p=caravanPoliticsRecord('river');__p.influence=20;__p.rivalStrength=30;window.__why=caravanPoliticsIssue('decree','river','toll');");assert.ok(run('__why.includes("ağırlığı")'));});
test('v44 decree also requires reputation and influence thresholds',()=>{const {run}=game();run(setup+v44Member+"window.__p=caravanPoliticsRecord('river');__p.influence=12;window.__a=caravanPoliticsIssue('decree','river','toll');__p.influence=30;__t.guild.reputation=30;window.__b=caravanPoliticsIssue('decree','river','toll');");assert.ok(run('__a.includes("20 nüfuz")'));assert.ok(run('__b.includes("36")'));});
test('v44 passing regional decree transfers 8 to NPC, spends 20 influence, grants 12-month policy',()=>{const {run}=game();run(setup+v44Member+"window.__p=caravanPoliticsRecord('river');__p.influence=50;window.__cash=s.wealth;window.__npc=__n.wealth;window.__ok=caravanPoliticsAction('decree','river','toll');");assert.equal(run('__ok'),true);assert.equal(run('s.wealth'),run('__cash-8'));assert.equal(run('__n.wealth'),run('__npc+8'));assert.equal(run('__p.influence'),30);assert.equal(run('__p.policy.kind'),'toll');assert.equal(run('__p.policy.until-__p.lastDecreeSerial'),12);});
test('v44 toll policy applies to member region only, not unrelated routes',()=>{const {run}=game();run(setup+v44Member+"window.__p=caravanPoliticsRecord('river');__p.influence=50;caravanPoliticsAction('decree','river','toll');s.pendingEventId=null;s.pendingDecision=null;window.__t=ensureCaravanTrade();__t.cargo=[{goodId:'salt',qty:1,unitCost:2}];s.monthsRemaining=9;window.__ok=caravanAction('depart','river');");assert.equal(run('__ok'),true);assert.equal(run('ensureCaravanTrade().trip.fee'),0);assert.equal(run('caravanPoliticsPolicy("mountain")'),null);});
test('v44 fair-price decree increases new quotes only for active member market',()=>{const {run}=game();run(setup+v44Fixture+"window.__n=caravanEnsureRival('mountain');window.__t=ensureCaravanTrade();__t.guild.routeId='mountain';__t.guild.sponsorId=__n.id;__t.guild.reputation=60;window.__p=caravanPoliticsRecord('mountain');__p.influence=50;window.__before=caravanQuote('mountain').silk;window.__outside=caravanQuote('river').silk;caravanPoliticsAction('decree','mountain','fair');window.__after=caravanQuote('mountain').silk;");assert.ok(run('__after>__before'));assert.equal(run('caravanQuote("river").silk'),run('__outside'));});
test('v44 policy cannot re-enact while active or before 12-month cooldown',()=>{const {run}=game();run(setup+v44Member+"window.__p=caravanPoliticsRecord('river');__p.influence=100;caravanPoliticsAction('decree','river','toll');window.__again=caravanPoliticsIssue('decree','river','fair');__p.policy=null;window.__cool=caravanPoliticsIssue('decree','river','fair');");assert.ok(run('__again.includes("yürürlükteki")'));assert.ok(run('__cool.includes("on iki ay")'));});
test('v44 quarterly council runs once and rival strength reflects actual NPC trading',()=>{const {run}=game();run(setup+v44Member+"window.__p=caravanPoliticsRecord('river');__p.influence=10;window.__rec=ensureCaravanTrade().competition.river;__rec.sold=2;__rec.lastCycleSerial=lifeSerial();Math.random=()=>.99;caravanPoliticsQuarterTick(3);window.__standing=__p.rivalStrength;window.__influence=__p.influence;caravanPoliticsQuarterTick(3);");assert.equal(run('__p.rivalStrength'),run('__standing'));assert.equal(run('__p.influence'),run('__influence'));assert.equal(run('__p.influence'),9);});
test('v44 policy expires automatically after passage of 12 months',()=>{const {run}=game();run(setup+v44Member+"window.__p=caravanPoliticsRecord('river');__p.policy={kind:'toll',until:lifeSerial()+1,sponsorId:__n.id};s.monthsRemaining=6;Math.random=()=>.99;caravanPoliticsQuarterTick(3);");assert.equal(run('caravanPoliticsRecord("river").policy'),null);assert.equal(run('caravanPoliticsPolicy("river")'),null);});
test('v44 dead NPC or leaving guild immediately cancels political benefit',()=>{const {run}=game();run(setup+v44Member+"window.__p=caravanPoliticsRecord('river');__p.policy={kind:'toll',until:lifeSerial()+12,sponsorId:__n.id};window.__on=caravanPoliticsPolicy('river');__n.alive=false;window.__off=caravanPoliticsPolicy('river');__n.alive=true;__t.guild.routeId=null;window.__out=caravanPoliticsPolicy('river');");assert.ok(run('__on!==null'));assert.equal(run('__off'),null);assert.equal(run('__out'),null);});
test('v44 active voyage price lock survives new guild decree',()=>{const {run}=game();run(setup+v44Member+"window.__t=ensureCaravanTrade();__t.cargo=[{goodId:'silk',qty:2,unitCost:3}];Math.random=()=>.99;caravanAction('depart','river');window.__locked=__t.prices.silk;window.__p=caravanPoliticsRecord('river');__p.policy={kind:'fair',until:lifeSerial()+12,sponsorId:__n.id};");assert.equal(run('ensureCaravanTrade().prices.silk'),run('__locked'));});
test('v44 guild political councils save and load with NPC policy sponsorship',()=>{const {run}=game();run(setup+v44Member+"window.__p=caravanPoliticsRecord('river');__p.influence=60;caravanPoliticsAction('decree','river','toll');window.__end=caravanPoliticsRecord('river').policy.until;save();load();");assert.equal(run('caravanPoliticsRecord("river").policy.until'),run('__end'));assert.equal(run('caravanPoliticsRecord("river").influence'),40);assert.equal(run('ensureCaravanTrade().guild.sponsorId'),run('__n.id'));});
test('v44 forged policy and impossible influence get scrubbed on migration',()=>{const {run}=game();run(setup+v44Member+"window.__p=caravanPoliticsRecord('river');__p.influence=500;__p.rivalStrength=-20;__p.policy={kind:'forged',until:500,sponsorId:'x'};__p.history=Array.from({length:100},()=>({kind:'bad'}));ensureCaravanTrade();");assert.equal(run('caravanPoliticsRecord("river").influence'),100);assert.equal(run('caravanPoliticsRecord("river").rivalStrength'),0);assert.equal(run('caravanPoliticsRecord("river").policy'),null);assert.equal(run('caravanPoliticsRecord("river").history.length'),30);});
test('v44 heir gets political history but no previous-life influence or decrees',()=>{const {run}=game();run(setup+v44Member+"window.__p=caravanPoliticsRecord('river');__p.influence=50;__p.policy={kind:'toll',until:lifeSerial()+12,sponsorId:__n.id};window.__heir=caravanInheritance(s,{assets:['caravan_share']});");assert.equal(run('__heir.guild.politics.river.influence'),0);assert.equal(run('__heir.guild.politics.river.policy'),null);assert.equal(run('__heir.guild.reputation'),0);});
test('v44 loading a v43 save creates backup and initializes rival power',()=>{const {run,storage}=game();run(setup+v44Member+"s.version=43;delete s.caravanTrade.guild.politics;save();load();");assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v44'));assert.equal(run('caravanPoliticsRecord("river").rivalStrength'),12);});
test('v44 council UI shows decisions and real regional influence',()=>{const {run}=game();run(setup+v44Member+"window.__markup=caravanPoliticsSummaryHtml();");assert.ok(run('__markup.includes("Lonca Rekabeti")'));assert.ok(run('__markup.includes("Geçiş kolaylığı")'));assert.ok(run('__markup.includes("Nüfuz")'));});


/* v45: true-NPC cross-regional alliance, rivalry, mediation, succession */
const v45Fixture="s.age=30;s.wealth=350;s.health=100;s.skill=100;s.prestige=80;s.skills.trade=70;s.assets.push('caravan_share');s.monthsRemaining=9;s.pendingEventId=null;s.pendingDecision=null;s.military.active=false;s.captive=false;ensureEconomy();";
const v45Guild=v45Fixture+"window.__a=caravanEnsureRival('river');window.__b=caravanEnsureRival('mountain');window.__t=ensureCaravanTrade();__t.guild.routeId='river';__t.guild.sponsorId=__a.id;__t.guild.reputation=60;__t.guild.politics.river.influence=75;";
const v45Alliance=v45Guild+"window.__p=caravanDiplomacyRecord('river','mountain');window.__ok=caravanDiplomacyAction('alliance','mountain');s.pendingEventId=null;s.pendingDecision=null;";
const v45Conflict=v45Alliance+"window.__ra=__t.competition.river;window.__rb=__t.competition.mountain;__ra.sold=1;__rb.sold=1;__ra.lastCycleSerial=lifeSerial();__rb.lastCycleSerial=lifeSerial();Math.random=()=>0;caravanDiplomacyQuarterTick(3);";
test('v45 fresh game has exactly three canonical regional diplomacy pairs',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.equal(run('Object.keys(ensureCaravanTrade().guild.diplomacy).length'),3);assert.equal(run('caravanDiplomacyRecord("river","mountain")===caravanDiplomacyRecord("mountain","river")'),true);});
test('v45 diplomacy is restricted to adult caravan owners',()=>{const {run}=game();run(setup+"window.__no=caravanDiplomacyIssue('alliance','mountain');s.assets.push('caravan_share');s.age=15;window.__young=caravanDiplomacyIssue('alliance','mountain');");assert.ok(run('__no.includes("yetişkin")'));assert.ok(run('__young.includes("yetişkin")'));});
test('v45 a non-member cannot forge cross-regional agreements',()=>{const {run}=game();run(setup+v45Fixture+"window.__why=caravanDiplomacyIssue('alliance','mountain');");assert.ok(run('__why.includes("Önce")'));});
test('v45 agreement needs 48 trade reputation and 30 regional influence',()=>{const {run}=game();run(setup+v45Guild+"__t.guild.reputation=47;window.__rep=caravanDiplomacyIssue('alliance','mountain');__t.guild.reputation=60;__t.guild.politics.river.influence=29;window.__inf=caravanDiplomacyIssue('alliance','mountain');");assert.ok(run('__rep.includes("48")'));assert.ok(run('__inf.includes("30")'));});
test('v45 alliance transfers exactly six to two real NPC wallets',()=>{const {run}=game();run(setup+v45Guild+"window.__pc=s.wealth;window.__ca=__a.wealth;window.__cb=__b.wealth;window.__done=caravanDiplomacyAction('alliance','mountain');");assert.equal(run('__done'),true);assert.equal(run('s.wealth'),run('__pc-6'));assert.equal(run('__a.wealth'),run('__ca+3'));assert.equal(run('__b.wealth'),run('__cb+3'));assert.equal(run('caravanDiplomacyRecord("river","mountain").status'),'allied');assert.equal(run('__t.guild.politics.river.influence'),45);});
test('v45 alliance cannot be purchased again before it expires',()=>{const {run}=game();run(setup+v45Alliance+"window.__cash=s.wealth;window.__again=caravanDiplomacyIssue('alliance','mountain');");assert.ok(run('__again.includes("bekleme")'));assert.equal(run('s.wealth'),run('__cash'));});
test('v45 benefits apply to two signatory markets, not a third route',()=>{const {run}=game();run(setup+v45Alliance);assert.equal(run('caravanDiplomacyToll("river")'),-1);assert.equal(run('caravanDiplomacyToll("mountain")'),-1);assert.equal(run('caravanDiplomacyToll("steppe")'),0);assert.ok(run('caravanDiplomacyTradeFactor("mountain")>1'));assert.equal(run('caravanDiplomacyTradeFactor("steppe")'),1);});
test('v45 bilateral alliance improves new quotes in partner territory',()=>{const {run}=game();run(setup+v45Guild+"window.__price=caravanQuote('mountain').silk;window.__third=caravanQuote('steppe').silk;caravanDiplomacyAction('alliance','mountain');");assert.ok(run('caravanQuote("mountain").silk>__price'));assert.equal(run('caravanQuote("steppe").silk'),run('__third'));});
test('v45 real signatory death immediately suspends alliance benefits',()=>{const {run}=game();run(setup+v45Alliance+"window.__benefit=caravanDiplomacyTradeFactor('mountain');__b.alive=false;");assert.ok(run('__benefit>1'));assert.equal(run('caravanDiplomacyTradeFactor("mountain")'),1);assert.equal(run('caravanDiplomacyToll("mountain")'),0);});
test('v45 two trading rivals can trigger persistent bilateral dispute',()=>{const {run}=game();run(setup+v45Conflict);assert.equal(run('__p.status'),'dispute');assert.equal(run('__p.disputes'),1);assert.ok(run('__p.until>lifeSerial()'));});
test('v45 quarterly diplomatic dispute triggers exactly once',()=>{const {run}=game();run(setup+v45Conflict+"window.__num=__p.disputes;window.__log=__p.history.length;caravanDiplomacyQuarterTick(3);");assert.equal(run('__p.disputes'),run('__num'));assert.equal(run('__p.history.length'),run('__log'));});
test('v45 political dispute worsens quotes and toll in affected markets',()=>{const {run}=game();run(setup+v45Conflict);assert.ok(run('caravanDiplomacyTradeFactor("mountain")<1'));assert.equal(run('caravanDiplomacyToll("river")'),1);assert.equal(run('caravanDiplomacyToll("steppe")'),0);});
test('v45 arbitration checks regional influence and available funds',()=>{const {run}=game();run(setup+v45Conflict+"__t.guild.politics.river.influence=9;window.__low=caravanDiplomacyIssue('mediate','mountain');__t.guild.politics.river.influence=50;s.wealth=4;window.__poor=caravanDiplomacyIssue('mediate','mountain');");assert.ok(run('__low.includes("10")'));assert.ok(run('__poor.includes("5 servet")'));});
