test('v45 mediated rivals must observe a cooling-off period',()=>{const {run}=game();run(setup+v45Conflict+"caravanDiplomacyAction('mediate','mountain');window.__why=caravanDiplomacyIssue('alliance','mountain');");assert.ok(run('__why.includes("bekleme")'));});
test('v45 siding pays only one NPC and permanently changes both relationships',()=>{const {run}=game();run(setup+v45Conflict+"window.__x=__a.rel;window.__y=__b.rel;window.__cash=__a.wealth;window.__pc=s.wealth;window.__ok2=caravanDiplomacyAction('support','mountain','river');window.__again=caravanDiplomacyIssue('support','mountain','river');");assert.equal(run('__ok2'),true);assert.equal(run('s.wealth'),run('__pc-3'));assert.equal(run('__a.wealth'),run('__cash+3'));assert.ok(run('__a.rel>__x'));assert.ok(run('__b.rel<__y'));assert.ok(run('__again.includes("daha önce")'));});
test('v45 siding with a nonparticipating region is disallowed',()=>{const {run}=game();run(setup+v45Conflict+"window.__issue=caravanDiplomacyIssue('support','mountain','steppe');");assert.ok(run('__issue.includes("bulunamadı")'));});
test('v45 expired treaty clears status and imposes cooldown exactly once',()=>{const {run}=game();run(setup+v45Alliance+"__p.until=lifeSerial()-1;caravanDiplomacyQuarterTick(3);window.__len=__p.history.length;caravanDiplomacyQuarterTick(3);");assert.equal(run('__p.status'),'neutral');assert.equal(run('__p.history[0].kind'),'expired');assert.equal(run('__p.history.length'),run('__len'));assert.ok(run('__p.coolingUntil>=lifeSerial()'));});
test('v45 outgoing caravan sale prices stay frozen after diplomacy changes',()=>{const {run}=game();run(setup+v45Guild+"window.__t=ensureCaravanTrade();__t.cargo=[{goodId:'silk',qty:1,unitCost:3}];Math.random=()=>.99;caravanAction('depart','mountain');window.__locked=__t.prices.silk;window.__p=caravanDiplomacyRecord('river','mountain');__p.status='allied';__p.until=lifeSerial()+18;__p.npcA=__b.id;__p.npcB=__a.id;");assert.equal(run('ensureCaravanTrade().prices.silk'),run('__locked'));});
