test('v45 malformed diplomatic history and status get normalized',()=>{const {run}=game();run(setup+v45Guild+"window.__p=caravanDiplomacyRecord('river','mountain');__p.status='fake';__p.history=Array.from({length:100},()=>({kind:'fake'}));__p.until=-99;ensureCaravanTrade();");assert.equal(run('__p.status'),'neutral');assert.equal(run('__p.history.length'),30);assert.equal(run('__p.until'),0);});
