/* v46 — NPC-financed allied convoys and real inventory escrow. */
const v46Base="s.age=30;s.wealth=350;s.health=100;s.skill=100;s.prestige=80;s.skills.trade=70;s.assets.push('caravan_share');s.monthsRemaining=9;s.pendingEventId=null;s.pendingDecision=null;s.military.active=false;s.captive=false;ensureEconomy();";
const v46Ready=v46Base+"window.__seller=caravanEnsureRival('river');window.__buyer=caravanEnsureRival('mountain');window.__t=ensureCaravanTrade();window.__sr=__t.competition.river;window.__br=__t.competition.mountain;window.__g=__t.guild;__g.routeId='river';__g.sponsorId=__seller.id;__g.reputation=60;__g.politics.river.influence=60;window.__d=caravanDiplomacyRecord('river','mountain');__d.status='allied';__d.npcA=__buyer.id;__d.npcB=__seller.id;__d.until=lifeSerial()+24;__sr.inventory=[{goodId:'silk',qty:2,unitCost:4}];__br.inventory=[];__buyer.wealth=500;Math.random=()=>.99;";
const v46Sent=v46Ready+"window.__sent=caravanConvoyAction('mountain','silk');s.pendingEventId=null;s.pendingDecision=null;window.__q=ensureCaravanTrade().guild.convoys.active;";
test('v46 blank registry and current save version',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.equal(run('ensureCaravanTrade().guild.convoys.active'),null);assert.equal(run('ensureCaravanTrade().guild.convoys.delivered'),0);});
test('v46 adults and actual caravan ownership required',()=>{const {run}=game();run(setup+"window.__a=caravanConvoyIssue('dispatch','mountain','silk');s.assets.push('caravan_share');s.age=15;window.__b=caravanConvoyIssue('dispatch','mountain','silk');");assert.ok(run('__a.includes("yetişkin")'));assert.ok(run('__b.includes("yetişkin")'));});
test('v46 no alliance or another region prevents dispatch',()=>{const {run}=game();run(setup+v46Ready+"__d.status='neutral';window.__no=caravanConvoyIssue('dispatch','mountain','silk');window.__same=caravanConvoyIssue('dispatch','river','silk');");assert.ok(run('__no.includes("ittifakı")'));assert.ok(run('__same.includes("farklı")'));});
test('v46 unstocked good and insolvent buyer stop shipment',()=>{const {run}=game();run(setup+v46Ready+"window.__no=caravanConvoyIssue('dispatch','mountain','iron');__buyer.wealth=0;window.__poor=caravanConvoyIssue('dispatch','mountain','silk');");assert.ok(run('__no.includes("stoku")'));assert.ok(run('__poor.includes("nakdi")'));});
test('v46 buyer warehouse capacity and reputation controls',()=>{const {run}=game();run(setup+v46Ready+"__br.inventory=[{goodId:'salt',qty:8,unitCost:2}];window.__full=caravanConvoyIssue('dispatch','mountain','silk');__br.inventory=[];__g.reputation=47;window.__rank=caravanConvoyIssue('dispatch','mountain','silk');");assert.ok(run('__full.includes("ambarı")'));assert.ok(run('__rank.includes("48")'));});
test('v46 dispatch moves exactly one real seller item and escrows buyer money',()=>{const {run}=game();run(setup+v46Ready+"window.__pc=s.wealth;window.__sc=__seller.wealth;window.__bc=__buyer.wealth;window.__ok=caravanConvoyAction('mountain','silk');window.__q=ensureCaravanTrade().guild.convoys.active;");assert.equal(run('__ok'),true);assert.equal(run('caravanRivalUnits(__sr)'),1);assert.equal(run('caravanRivalUnits(__br)'),0);assert.equal(run('__buyer.wealth'),run('__bc-__q.price'));assert.equal(run('__seller.wealth'),run('__sc'));assert.equal(run('s.wealth'),run('__pc'));});
test('v46 offer locks a profitable cash-conserving quote with explicit commission',()=>{const {run}=game();run(setup+v46Sent);assert.ok(run('__q.price>__q.unitCost'));assert.ok(run('__q.commission>=1'));assert.ok(run('__q.commission<__q.price'));assert.equal(run('__q.qty'),1);});
test('v46 only one dispatch at a time and cooldown after send',()=>{const {run}=game();run(setup+v46Sent+"window.__again=caravanConvoyIssue('dispatch','mountain','silk');__g.convoys.active=null;window.__cool=caravanConvoyIssue('dispatch','mountain','silk');");assert.ok(run('__again.includes("mevcut")'));assert.ok(run('__cool.includes("altı ay")'));});
test('v46 real settlement gives seller price-minus-fee, buyer goods, player only fee',()=>{const {run}=game();run(setup+v46Ready+"window.__pc=s.wealth;window.__sc=__seller.wealth;window.__bc=__buyer.wealth;caravanConvoyAction('mountain','silk');window.__q=__g.convoys.active;window.__price=__q.price;window.__fee=__q.commission;s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;s.monthsRemaining=4;window.__settled=caravanConvoyMonthTick();");assert.equal(run('__seller.wealth'),run('__sc+__price-__fee'));assert.equal(run('s.wealth'),run('__pc+__fee'));assert.equal(run('__buyer.wealth'),run('__bc-__price'));assert.equal(run('caravanRivalUnits(__br)'),1);assert.equal(run('__g.convoys.delivered'),1);});
test('v46 cash is conserved between player and both true NPCs',()=>{const {run}=game();run(setup+v46Ready+"window.__cash=s.wealth+__seller.wealth+__buyer.wealth;caravanConvoyAction('mountain','silk');s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;s.monthsRemaining=4;caravanConvoyMonthTick();");assert.equal(run('s.wealth+__seller.wealth+__buyer.wealth'),run('__cash'));});
test('v46 settlement is idempotent: no duplicate merchandise or payment',()=>{const {run}=game();run(setup+v46Sent+"s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;s.monthsRemaining=4;caravanConvoyMonthTick();window.__wealth=s.wealth;window.__stock=caravanRivalUnits(__br);caravanConvoyMonthTick();");assert.equal(run('s.wealth'),run('__wealth'));assert.equal(run('caravanRivalUnits(__br)'),run('__stock'));assert.equal(run('__g.convoys.delivered'),1);});
test('v46 departure and arrival do not fabricate public commodity market supply',()=>{const {run}=game();run(setup+v46Ready+"window.__source=caravanMarketState('river').goods.silk.supply;window.__dest=caravanMarketState('mountain').goods.silk.supply;caravanConvoyAction('mountain','silk');s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;s.monthsRemaining=4;caravanConvoyMonthTick();");assert.equal(run('caravanMarketState("river").goods.silk.supply'),run('__source'));assert.equal(run('caravanMarketState("mountain").goods.silk.supply'),run('__dest'));});
test('v46 recipient warehouse is reserved against autonomous NPC purchases',()=>{const {run}=game();run(setup+v46Sent+"__br.inventory=[{goodId:'salt',qty:7,unitCost:2}];caravanRivalCycle(3);");assert.ok(run('caravanRivalUnits(__br)<=7'));});
test('v46 seller warehouse has reserved return slot during transit',()=>{const {run}=game();run(setup+v46Sent+"__sr.inventory=[{goodId:'wool',qty:7,unitCost:2}];caravanRivalCycle(3);");assert.ok(run('caravanRivalUnits(__sr)<=7'));});
test('v46 wholesale cannot fill space reserved for arriving convoy',()=>{const {run}=game();run(setup+v46Sent+"__br.inventory=[{goodId:'salt',qty:7,unitCost:2}];__t.stage='market';__t.routeId='mountain';__t.cargo=[{goodId:'iron',qty:1,unitCost:4}];window.__why=caravanWholesaleIssue('iron');");assert.ok(run('__why.includes("ambarı")'));});
test('v46 live player contract cannot use warehouse reserved by convoy',()=>{const {run}=game();run(setup+v46Sent+"__br.inventory=[{goodId:'salt',qty:7,unitCost:2}];__t.stage='home';__t.contracts.offers=[{id:'xyz',issuerId:__buyer.id,routeId:'mountain',goodId:'iron',qty:1,reward:5,validUntil:lifeSerial()+5}];window.__why=caravanContractIssue('accept','xyz');");assert.ok(run('__why.includes("ambarı")'));});
test('v46 buyer death returns escrow and restores seller cargo when possible',()=>{const {run}=game();run(setup+v46Ready+"window.__wallet=__buyer.wealth;caravanConvoyAction('mountain','silk');__buyer.alive=false;caravanConvoyMonthTick();");assert.equal(run('__buyer.wealth'),run('__wallet'));assert.equal(run('caravanRivalUnits(__sr)'),2);assert.equal(run('__g.convoys.cancelled'),1);});
test('v46 owner cancellation refunds buyer without creating silver or silk',()=>{const {run}=game();run(setup+v46Ready+"window.__wallet=__buyer.wealth;window.__player=s.wealth;caravanConvoyAction('mountain','silk');window.__done=caravanConvoyFinish('cancelled','test');");assert.equal(run('__done'),true);assert.equal(run('__buyer.wealth'),run('__wallet'));assert.equal(run('s.wealth'),run('__player'));assert.equal(run('caravanRivalUnits(__sr)'),2);});
test('v46 invalid second cancel cannot refund escrow twice',()=>{const {run}=game();run(setup+v46Ready+"caravanConvoyAction('mountain','silk');caravanConvoyFinish('cancelled','test');window.__cash=__buyer.wealth;window.__again=caravanConvoyFinish('cancelled','repeat');");assert.equal(run('__again'),false);assert.equal(run('__buyer.wealth'),run('__cash'));});
test('v46 no settlement payout before physical arrival',()=>{const {run}=game();run(setup+v46Sent+"window.__cash=s.wealth;window.__arrives=__q.arrivalSerial;caravanConvoyMonthTick();");assert.equal(run('__g.convoys.delivered'),0);assert.equal(run('s.wealth'),run('__cash'));assert.ok(run('__q.arrivalSerial>lifeSerial()'));});
test('v46 signed alliance can become disputed during transit without repricing escrow',()=>{const {run}=game();run(setup+v46Sent+"window.__price=__q.price;__d.status='dispute';__d.until=lifeSerial()+9;s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;s.monthsRemaining=4;caravanConvoyMonthTick();");assert.equal(run('__g.convoys.delivered'),1);assert.equal(run('__g.convoys.history[0].price'),run('__price'));});
test('v46 active consignment persists through browser save and load',()=>{const {run}=game();run(setup+v46Sent+"window.__price=__q.price;save();load();");assert.equal(run('ensureCaravanTrade().guild.convoys.active.price'),run('__price'));assert.equal(run('caravanConvoyReservedUnits(__buyer.id)'),1);});
test('v46 inherited trade history never transfers an active brokerage deal',()=>{const {run}=game();run(setup+v46Sent+"window.__heir=caravanInheritance(s,{assets:['caravan_share']});");assert.equal(run('__heir.guild.convoys.active'),null);assert.equal(run('ensureCaravanTrade().guild.convoys.active!==null'),true);});
test('v46 invalid forged consignment and enormous history are sanitized',()=>{const {run}=game();run(setup+v46Ready+"__g.convoys.active={id:'fake',origin:'river',dest:'mountain',goodId:'salt',qty:999,price:999999,sellerId:'a',buyerId:'b'};__g.convoys.history=Array.from({length:100},()=>({status:'fake'}));ensureCaravanTrade();");assert.equal(run('__g.convoys.active'),null);assert.equal(run('__g.convoys.history.length'),30);});
test('v46 old v45 save migrates and keeps earlier caravan rival identity',()=>{const {run,storage}=game();run(setup+v46Ready+"window.__id=__seller.id;s.version=45;delete s.caravanTrade.guild.convoys;save();load();");assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v46'));assert.equal(run('ensureCaravanTrade().competition.river.npcId'),run('__id'));});
test('v46 UI exposes living merchant shipment and real escrow amounts',()=>{const {run}=game();run(setup+v46Sent+"window.__ui=caravanConvoySummaryHtml();");assert.ok(run('__ui.includes("Ortak Lonca Sevkiyatları")'));assert.ok(run('__ui.includes("Emanet")'));assert.ok(run('__ui.includes("Aracı payı")'));});


/* v47 — insured merchant cargo, reserve escrow, real road losses. */
const v47R=v46Ready+"window.__ins=caravanEnsureRival('steppe');__ins.wealth=100;Math.random=()=>.99;";
const v47S=v47R+"window.__cash=s.wealth;window.__w=__ins.wealth;window.__sellerWallet=__seller.wealth;window.__buyerWallet=__buyer.wealth;window.__sent=caravanConvoyAction('mountain','silk',true);s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;window.__q=ensureCaravanTrade().guild.convoys.active;";
test('v47 new characters start with no losses or claims',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.equal(run('ensureCaravanTrade().guild.convoys.lost'),0);assert.equal(run('ensureCaravanTrade().guild.convoys.claimsPaid'),0);});
test('v47 insurance must be funded by independent third living NPC',()=>{const {run}=game();run(setup+v46Ready+"window.__issue=caravanConvoyIssue('dispatch','mountain','silk',true);");assert.ok(run('__issue.includes("üçüncü")'));});
test('v47 underwriter cannot promise reserve without wealth',()=>{const {run}=game();run(setup+v47R+"__ins.wealth=0;window.__issue=caravanConvoyIssue('dispatch','mountain','silk',true);");assert.ok(run('__issue.includes("teminat")'));});
test('v47 player needs two real coins for insurance premium',()=>{const {run}=game();run(setup+v47R+"s.wealth=1;window.__issue=caravanConvoyIssue('dispatch','mountain','silk',true);");assert.ok(run('__issue.includes("2 servet")'));});
test('v47 dispatch keeps a real insurer reserve and transfers premium',()=>{const {run}=game();run(setup+v47S);assert.equal(run('__sent'),true);assert.equal(run('s.wealth'),run('__cash-2'));assert.equal(run('__q.insurance.coverage'),run('__q.unitCost'));assert.equal(run('__ins.wealth'),run('__w-__q.unitCost+2'));assert.equal(run('__buyer.wealth'),run('__buyerWallet-__q.price'));});
test('v47 ordinary old convoy stays without insurance or premium',()=>{const {run}=game();run(setup+v47R+"window.__cash=s.wealth;caravanConvoyAction('mountain','silk');window.__q=ensureCaravanTrade().guild.convoys.active;");assert.equal(run('__q.insurance'),null);assert.equal(run('s.wealth'),run('__cash'));});
test('v47 delivered insurance returns full coverage to underwriter',()=>{const {run}=game();run(setup+v47S+"s.monthsRemaining=4;caravanConvoyMonthTick();");assert.equal(run('ensureCaravanTrade().guild.convoys.delivered'),1);assert.equal(run('ensureCaravanTrade().guild.convoys.lost'),0);assert.equal(run('__ins.wealth'),run('__w+2'));});
test('v47 insured road loss pays seller coverage and refunds buyer escrow',()=>{const {run}=game();run(setup+v47S+"s.monthsRemaining=7;Math.random=()=>0;caravanConvoyMonthTick();");assert.equal(run('ensureCaravanTrade().guild.convoys.lost'),1);assert.equal(run('__buyer.wealth'),run('__buyerWallet'));assert.equal(run('__seller.wealth'),run('__sellerWallet+__q.unitCost'));assert.equal(run('__ins.wealth'),run('__w-__q.unitCost+2'));assert.equal(run('ensureCaravanTrade().guild.convoys.claimsPaid'),run('__q.unitCost'));assert.equal(run('caravanRivalUnits(__sr)'),1);assert.equal(run('caravanRivalUnits(__br)'),0);});
test('v47 uninsured loss is physical loss and no fake money is awarded',()=>{const {run}=game();run(setup+v47R+"window.__b=__buyer.wealth;window.__s=__seller.wealth;caravanConvoyAction('mountain','silk');s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;s.monthsRemaining=7;Math.random=()=>0;caravanConvoyMonthTick();");assert.equal(run('ensureCaravanTrade().guild.convoys.lost'),1);assert.equal(run('__buyer.wealth'),run('__b'));assert.equal(run('__seller.wealth'),run('__s'));assert.equal(run('caravanRivalUnits(__sr)'),1);assert.equal(run('ensureCaravanTrade().guild.convoys.claimsPaid'),0);});
