test('v47 covered cancellation returns both real escrows without double payout',()=>{const {run}=game();run(setup+v47S+"window.__a=caravanConvoyFinish('cancelled','test');window.__b=caravanConvoyFinish('cancelled','again');");assert.equal(run('__a'),true);assert.equal(run('__b'),false);assert.equal(run('__ins.wealth'),run('__w+2'));assert.equal(run('__buyer.wealth'),run('__buyerWallet'));assert.equal(run('caravanRivalUnits(__sr)'),2);});
test('v47 insured loss preserves cash across four real parties',()=>{const {run}=game();run(setup+v47R+"window.__sum=s.wealth+__seller.wealth+__buyer.wealth+__ins.wealth;caravanConvoyAction('mountain','silk',true);s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;s.monthsRemaining=7;Math.random=()=>0;caravanConvoyMonthTick();");assert.equal(run('s.wealth+__seller.wealth+__buyer.wealth+__ins.wealth'),run('__sum'));});
