test('v47 risk evaluated at most once in the same calendar month',()=>{const {run}=game();run(setup+v47S+"s.monthsRemaining=7;window.__calls=0;Math.random=()=>{window.__calls++;return .99};caravanConvoyMonthTick();caravanConvoyMonthTick();");assert.equal(run('__calls'),1);assert.ok(run('ensureCaravanTrade().guild.convoys.active!==null'));});
test('v47 cargo safely arriving has no last-minute random loss',()=>{const {run}=game();run(setup+v47S+"s.monthsRemaining=4;Math.random=()=>0;caravanConvoyMonthTick();");assert.equal(run('ensureCaravanTrade().guild.convoys.lost'),0);assert.equal(run('ensureCaravanTrade().guild.convoys.delivered'),1);});
test('v47 insurance loss cannot fabricate public market goods',()=>{const {run}=game();run(setup+v47S+"window.__from=caravanMarketState('river').goods.silk.supply;window.__to=caravanMarketState('mountain').goods.silk.supply;s.monthsRemaining=7;Math.random=()=>0;caravanConvoyMonthTick();");assert.equal(run('caravanMarketState("river").goods.silk.supply'),run('__from'));assert.equal(run('caravanMarketState("mountain").goods.silk.supply'),run('__to'));});
test('v47 insurer and reserved value survive browser save-load',()=>{const {run}=game();run(setup+v47S+"window.__id=__q.insurance.insurerId;save();load();");assert.equal(run('ensureCaravanTrade().guild.convoys.active.insurance.insurerId'),run('__id'));assert.equal(run('ensureCaravanTrade().guild.convoys.active.insurance.coverage'),run('__q.unitCost'));});
test('v47 invalid forged or self-funded insurance record is rejected',()=>{const {run}=game();run(setup+v47S+"__q.insurance={insurerId:__seller.id,coverage:9999,premium:2};ensureCaravanTrade();");assert.equal(run('ensureCaravanTrade().guild.convoys.active.insurance'),null);});
test('v47 heirs inherit trade ledger but not active insured shipment',()=>{const {run}=game();run(setup+v47S+"window.__heir=caravanInheritance(s,{assets:['caravan_share']});");assert.equal(run('__heir.guild.convoys.active'),null);assert.equal(run('ensureCaravanTrade().guild.convoys.active.insurance.insurerId'),run('__ins.id'));});
test('v47 migrates old v46 save without inventing insurance',()=>{const {run,storage}=game();run(setup+v46Ready+"s.version=46;delete s.caravanTrade.guild.convoys.lost;save();load();");assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v47'));assert.equal(run('ensureCaravanTrade().guild.convoys.lost'),0);});
test('v47 UI offers insured dispatch plus actual loss statistics',()=>{const {run}=game();run(setup+v47R+"window.__html=caravanConvoySummaryHtml();");assert.ok(run('__html.includes("Sigortalı")'));assert.ok(run('__html.includes("Kayıp")'));assert.ok(run('__html.includes("teminat")'));});


/* v48 — independently paid road escorts, convoy risk and real NPC money flows. */
const v48Ready=v47R+"window.__q0=null;";
const v48Sent=v48Ready+"window.__before=s.wealth;window.__npcBefore=__ins.wealth;window.__buyerBefore=__buyer.wealth;window.__sellerBefore=__seller.wealth;window.__ok=caravanConvoyAction('mountain','silk',false,true);s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;window.__q=ensureCaravanTrade().guild.convoys.active;";
test('v48 new save records escorted convoy count without mutating older statistics',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.equal(run('ensureCaravanTrade().guild.convoys.escorted'),0);assert.equal(run('ensureCaravanTrade().guild.convoys.lost'),0);});
test('v48 escort requires independent living third-market NPC',()=>{const {run}=game();run(setup+v46Ready+"window.__issue=caravanConvoyIssue('dispatch','mountain','silk',false,true);");assert.ok(run('__issue.includes("üçüncü")'));});
test('v48 escort is rejected without the three-coin fee',()=>{const {run}=game();run(setup+v48Ready+"s.wealth=2;window.__issue=caravanConvoyIssue('dispatch','mountain','silk',false,true);");assert.ok(run('__issue.includes("3 servet")'));assert.equal(run('ensureCaravanTrade().guild.convoys.escorted'),0);});
test('v48 escorted plus insured deal needs full five coins up front',()=>{const {run}=game();run(setup+v48Ready+"s.wealth=4;window.__issue=caravanConvoyIssue('dispatch','mountain','silk',true,true);");assert.ok(run('__issue.includes("5 servet")'));});
test('v48 escort cannot be hired from dead independent NPC',()=>{const {run}=game();run(setup+v48Ready+"__ins.alive=false;window.__issue=caravanConvoyIssue('dispatch','mountain','silk',false,true);");assert.ok(run('__issue.includes("yaşayan")'));});
test('v48 guard contract pays real NPC and retains original buyer escrow',()=>{const {run}=game();run(setup+v48Sent);assert.equal(run('__ok'),true);assert.equal(run('s.wealth'),run('__before-3'));assert.equal(run('__ins.wealth'),run('__npcBefore+3'));assert.equal(run('__buyer.wealth'),run('__buyerBefore-__q.price'));assert.equal(run('__seller.wealth'),run('__sellerBefore'));assert.equal(run('__q.escort.escortId'),run('__ins.id'));assert.equal(run('__q.insurance'),null);assert.equal(run('caravanRivalUnits(__sr)'),1);assert.equal(run('__g.convoys.escorted'),1);});
test('v48 real escort reduces but does not eliminate risk',()=>{const {run}=game();run(setup+v48Sent+"window.__guarded=caravanConvoyRisk(__q);window.__unguarded=caravanConvoyRisk({...__q,escort:null});");assert.ok(run('__guarded>0'));assert.ok(run('__guarded<__unguarded'));});
test('v48 combined escort and insurance reserve are funded from the same player purse',()=>{const {run}=game();run(setup+v48Ready+"window.__pw=s.wealth;window.__nw=__ins.wealth;caravanConvoyAction('mountain','silk',true,true);window.__q=ensureCaravanTrade().guild.convoys.active;");assert.equal(run('s.wealth'),run('__pw-5'));assert.equal(run('__ins.wealth'),run('__nw+5-__q.unitCost'));assert.equal(run('__q.insurance.insurerId'),run('__q.escort.escortId'));});
test('v48 guards can still lose physical cargo without printing claims',()=>{const {run}=game();run(setup+v48Sent+"s.monthsRemaining=7;Math.random=()=>0;caravanConvoyMonthTick();");assert.equal(run('__g.convoys.lost'),1);assert.equal(run('__g.convoys.claimsPaid'),0);assert.equal(run('__buyer.wealth'),run('__buyerBefore'));assert.equal(run('__ins.wealth'),run('__npcBefore+3'));assert.equal(run('caravanRivalUnits(__br)'),0);});
test('v48 guard payment is only made once even if settlement repeats',()=>{const {run}=game();run(setup+v48Sent+"s.monthsRemaining=4;caravanConvoyMonthTick();window.__money=__ins.wealth;caravanConvoyMonthTick();");assert.equal(run('__ins.wealth'),run('__money'));assert.equal(run('__ins.wealth'),run('__npcBefore+3'));assert.equal(run('__g.convoys.escorted'),1);assert.equal(run('__g.convoys.delivered'),1);});
test('v48 guard death ends protection without forging a fee refund',()=>{const {run}=game();run(setup+v48Sent+"window.__safe=caravanConvoyRisk(__q);__ins.alive=false;window.__unsafe=caravanConvoyRisk(__q);");assert.ok(run('__unsafe>__safe'));assert.equal(run('__ins.wealth'),run('__npcBefore+3'));});
test('v48 insured guarded loss funds seller and preserves total real cash',()=>{const {run}=game();run(setup+v48Ready+"window.__sum=s.wealth+__ins.wealth+__seller.wealth+__buyer.wealth;caravanConvoyAction('mountain','silk',true,true);s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;s.monthsRemaining=7;Math.random=()=>0;caravanConvoyMonthTick();");assert.equal(run('s.wealth+__ins.wealth+__seller.wealth+__buyer.wealth'),run('__sum'));assert.equal(run('__g.convoys.lost'),1);assert.equal(run('__g.convoys.claimsPaid'),4);});
test('v48 guard dispatch survives browser save and load',()=>{const {run}=game();run(setup+v48Sent+"save();load();");assert.equal(run('ensureCaravanTrade().guild.convoys.active.escort.escortId'),run('__ins.id'));assert.equal(run('ensureCaravanTrade().guild.convoys.active.escort.fee'),3);});
test('v48 forged self-escort cannot survive normalization',()=>{const {run}=game();run(setup+v48Sent+"__q.escort={escortId:__seller.id,fee:3};ensureCaravanTrade();");assert.equal(run('__g.convoys.active.escort'),null);});
test('v48 malformed or free escort fee cannot survive normalization',()=>{const {run}=game();run(setup+v48Sent+"__q.escort={escortId:__ins.id,fee:0};ensureCaravanTrade();");assert.equal(run('__g.convoys.active.escort'),null);});
test('v48 a child inheriting caravan history never inherits active guard commitment',()=>{const {run}=game();run(setup+v48Sent+"window.__heir=caravanInheritance(s,{assets:['caravan_share']});");assert.equal(run('__heir.guild.convoys.active'),null);assert.equal(run('__heir.guild.convoys.escorted'),1);});
test('v48 converts old v47 saves without creating a fake escort and backs up the old save',()=>{const {run,storage}=game();run(setup+v47S+"delete __q.escort;delete __g.convoys.escorted;s.version=47;save();load();");assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v48'));assert.equal(run('ensureCaravanTrade().guild.convoys.active.escort'),null);assert.equal(run('ensureCaravanTrade().guild.convoys.escorted'),0);});
test('v48 UI offers normal insurance guard and combined options with risk preview',()=>{const {run}=game();run(setup+v48Ready+"window.__html=caravanConvoySummaryHtml();");assert.ok(run('__html.includes("Sigortalı + Muhafızlı")'));assert.ok(run('__html.includes("Muhafızlı:")'));run("caravanConvoyAction('mountain','silk',false,true);window.__html=caravanConvoySummaryHtml();");assert.ok(run('__html.includes("Aylık yol kaybı riski")'));});


/* v49 — real NPC courier payments, delivery acceleration and mid-route escort repair. */
const v49U=v48Ready+"window.__money=s.wealth;window.__merchant=__ins.wealth;window.__sent=caravanConvoyAction('mountain','silk');s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;window.__q=ensureCaravanTrade().guild.convoys.active;";
test('v49 new characters start without courier jobs or escort renewals',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.equal(run('ensureCaravanTrade().guild.convoys.expedited'),0);assert.equal(run('ensureCaravanTrade().guild.convoys.escortRenewals'),0);});
test('v49 management requires an active genuine consignment',()=>{const {run}=game();run(setup+v48Ready+"window.__err=caravanConvoyInterveneIssue('expedite');");assert.ok(run('__err.includes("sevkiyat")'));});
test('v49 third-market living courier is required for intervention',()=>{const {run}=game();run(setup+v46Sent+"window.__err=caravanConvoyInterveneIssue('expedite');");assert.ok(run('__err.includes("üçüncü")'));});
test('v49 player cannot pay courier fee with insufficient cash',()=>{const {run}=game();run(setup+v49U+"s.wealth=3;window.__m=s.monthsRemaining;window.__err=caravanConvoyInterveneIssue('expedite');window.__ok=caravanConvoyIntervene('expedite');");assert.equal(run('__ok'),false);assert.ok(run('__err.includes("4 servet")'));assert.equal(run('s.monthsRemaining'),run('__m'));});
test('v49 courier draws exactly four coins from player and gives them to real NPC',()=>{const {run}=game();run(setup+v49U+"__q.arrivalSerial=lifeSerial()+5;window.__oldArrival=__q.arrivalSerial;window.__bank=s.wealth;window.__npcBank=__ins.wealth;window.__ok=caravanConvoyIntervene('expedite');");assert.equal(run('__ok'),true);assert.equal(run('s.wealth'),run('__bank-4'));assert.equal(run('__ins.wealth'),run('__npcBank+4'));assert.equal(run('__q.arrivalSerial'),run('__oldArrival-1'));assert.equal(run('__q.expedite.priorArrivalSerial'),run('__oldArrival'));assert.equal(run('__g.convoys.expedited'),1);});
test('v49 fast courier increases travel risk while escort continues helping',()=>{const {run}=game();run(setup+v48Sent+"__q.arrivalSerial=lifeSerial()+5;window.__riskBefore=caravanConvoyRisk(__q);caravanConvoyIntervene('expedite');window.__riskAfter=caravanConvoyRisk(__q);");assert.ok(run('__riskAfter>__riskBefore'));assert.ok(run('__riskAfter<caravanConvoyRisk({...__q,escort:null})'));});
test('v49 rushing the original three-month route can arrive one action earlier',()=>{const {run}=game();run(setup+v49U+"window.__eta=__q.arrivalSerial;window.__ok=caravanConvoyIntervene('expedite');");assert.equal(run('__ok'),true);assert.equal(run('__q.arrivalSerial'),run('__eta-1'));assert.equal(run('__g.convoys.delivered'),1);assert.equal(run('__g.convoys.active'),null);});
test('v49 prevents a second courier charge on same convoy',()=>{const {run}=game();run(setup+v49U+"__q.arrivalSerial=lifeSerial()+6;caravanConvoyIntervene('expedite');s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;window.__cash=s.wealth;window.__months=s.monthsRemaining;window.__ok=caravanConvoyIntervene('expedite');");assert.equal(run('__ok'),false);assert.equal(run('s.wealth'),run('__cash'));assert.equal(run('s.monthsRemaining'),run('__months'));assert.equal(run('__g.convoys.expedited'),1);});
test('v49 cannot accelerate shipment already one month from destination',()=>{const {run}=game();run(setup+v49U+"__q.arrivalSerial=lifeSerial()+1;window.__err=caravanConvoyInterveneIssue('expedite');");assert.ok(run('__err.includes("iki ay")'));});
test('v49 trader can add a first escort mid-route without creating money',()=>{const {run}=game();run(setup+v49U+"__q.arrivalSerial=lifeSerial()+5;window.__pc=s.wealth;window.__npc=__ins.wealth;window.__beforeRisk=caravanConvoyRisk(__q);window.__ok=caravanConvoyIntervene('renewEscort');");assert.equal(run('__ok'),true);assert.equal(run('s.wealth'),run('__pc-3'));assert.equal(run('__ins.wealth'),run('__npc+3'));assert.equal(run('__q.escort.escortId'),run('__ins.id'));assert.ok(run('caravanConvoyRisk(__q)<__beforeRisk'));assert.equal(run('__g.convoys.escortRenewals'),1);assert.equal(run('__g.convoys.escorted'),1);});
test('v49 cannot buy a second guard while a living guard is employed',()=>{const {run}=game();run(setup+v48Sent+"window.__why=caravanConvoyInterveneIssue('renewEscort');");assert.ok(run('__why.includes("hâlâ")'));});
test('v49 mid-route guard replacement after death pays a different living NPC',()=>{const {run}=game();run(setup+v48Sent+"__q.arrivalSerial=lifeSerial()+6;__ins.alive=false;window.__new=caravanEnsureRival('steppe');window.__newCash=__new.wealth;window.__pc=s.wealth;window.__ok=caravanConvoyIntervene('renewEscort');");assert.equal(run('__ok'),true);assert.notEqual(run('__q.escort.escortId'),run('__ins.id'));assert.equal(run('__new.wealth'),run('__newCash+3'));assert.equal(run('s.wealth'),run('__pc-3'));assert.equal(run('__g.convoys.escorted'),1);assert.equal(run('__g.convoys.escortRenewals'),1);});
test('v49 guard reinforcements have a one-use lifetime per consignment',()=>{const {run}=game();run(setup+v49U+"__q.arrivalSerial=lifeSerial()+6;caravanConvoyIntervene('renewEscort');s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;__ins.alive=false;caravanEnsureRival('steppe');window.__cash=s.wealth;window.__m=s.monthsRemaining;window.__ok=caravanConvoyIntervene('renewEscort');");assert.equal(run('__ok'),false);assert.equal(run('s.wealth'),run('__cash'));assert.equal(run('s.monthsRemaining'),run('__m'));});
test('v49 escort renewal is not refunded after a cancelled voyage',()=>{const {run}=game();run(setup+v49U+"__q.arrivalSerial=lifeSerial()+5;window.__pc=s.wealth;window.__npc=__ins.wealth;caravanConvoyIntervene('renewEscort');caravanConvoyFinish('cancelled','test');");assert.equal(run('s.wealth'),run('__pc-3'));assert.equal(run('__ins.wealth'),run('__npc+3'));assert.equal(run('__g.convoys.cancelled'),1);});
test('v49 both contract addenda survive save and load before arrival',()=>{const {run}=game();run(setup+v49U+"__q.arrivalSerial=lifeSerial()+6;caravanConvoyIntervene('expedite');s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;caravanConvoyIntervene('renewEscort');save();load();window.__fresh=ensureCaravanTrade().guild.convoys.active;");assert.ok(run('__fresh!==null'));assert.equal(run('__fresh.expedite.fee'),4);assert.equal(run('__fresh.expedite.priorArrivalSerial'),run('__fresh.arrivalSerial+1'));assert.equal(run('__fresh.escortRenewed'),true);assert.equal(run('__fresh.escort.escortId'),run('__ins.id'));});
test('v49 malformed or impossible courier stamp cannot survive normalization',()=>{const {run}=game();run(setup+v49U+"__q.expedite={courierId:__ins.id,fee:4,acceleratedSerial:0,priorArrivalSerial:0};ensureCaravanTrade();");assert.equal(run('__g.convoys.active.expedite'),null);});
test('v49 courier accelerated history survives inheritance but not the active contract',()=>{const {run}=game();run(setup+v49U+"__q.arrivalSerial=lifeSerial()+6;caravanConvoyIntervene('expedite');window.__heir=caravanInheritance(s,{assets:['caravan_share']});");assert.equal(run('__heir.guild.convoys.active'),null);assert.equal(run('__heir.guild.convoys.expedited'),1);});
test('v49 insurance collateral is released once when invalid delivery becomes cancellation',()=>{const {run}=game();run(setup+v47S+"__seller.alive=false;window.__ok=caravanConvoyFinish('delivered','test');");assert.equal(run('__ok'),true);assert.equal(run('__g.convoys.cancelled'),1);assert.equal(run('__g.convoys.delivered'),0);assert.equal(run('__ins.wealth'),run('__w+2'));assert.equal(run('__buyer.wealth'),run('__buyerWallet'));});
test('v49 older v48 save migrates with archival backup and no fake addenda',()=>{const {run,storage}=game();run(setup+v49U+"s.version=48;delete __q.expedite;delete __q.escortRenewed;delete __g.convoys.expedited;delete __g.convoys.escortRenewals;save();load();");assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v49'));assert.equal(run('ensureCaravanTrade().guild.convoys.active.expedite'),null);assert.equal(run('ensureCaravanTrade().guild.convoys.escortRenewals'),0);});
test('v49 active caravan UI describes two actionable interventions and risk',()=>{const {run}=game();run(setup+v49U+"window.__html=caravanConvoySummaryHtml();");assert.ok(run('__html.includes("Acele haberci gönder")'));assert.ok(run('__html.includes("Muhafız takviyesi gönder")'));assert.ok(run('__html.includes("Aylık yol kaybı riski")'));});


/* v50 — NPC caravan road-block encounters, resolved choices, physical losses. */
const v50Road=v49U+"s.monthsRemaining=7;Math.random=()=>.10;caravanConvoyMonthTick();window.__bandit=npcById(__q.ambush.banditId);";
test('v50 new lives start without road encounters or paid bandit tolls',()=>{const {run}=game();assert.equal(run('s.version'),50);assert.equal(run('ensureCaravanTrade().guild.convoys.ambushes'),0);assert.equal(run('ensureCaravanTrade().guild.convoys.tollsPaid'),0);});
test('v50 near risk roll opens NPC encounter without losing physical silk',()=>{const {run}=game();run(setup+v50Road);assert.equal(run('__q.ambushHandled'),true);assert.ok(run('__bandit?.alive'));assert.equal(run('__bandit.type'),'Yol Kesici');assert.equal(run('caravanRivalUnits(__sr)'),1);assert.equal(run('__g.convoys.lost'),0);assert.equal(run('__g.convoys.ambushes'),1);});
test('v50 encountering a road blocker introduces a persistent independently named NPC',()=>{const {run}=game();run(setup+v50Road+"window.__id=__bandit.id;");assert.ok(run('s.careerContacts.some(n=>n.id===__id)'));assert.ok(run('__bandit.statusFlags.caravanBanditConvoy===__q.id'));});
test('v50 ordinary zero random roll still loses cargo without a new chance event',()=>{const {run}=game();run(setup+v49U+"s.monthsRemaining=7;Math.random=()=>0;caravanConvoyMonthTick();");assert.equal(run('__g.convoys.active'),null);assert.equal(run('__g.convoys.lost'),1);assert.equal(run('__g.convoys.ambushes'),0);});
test('v50 no random encounter or loss can happen on physical arrival month',()=>{const {run}=game();run(setup+v49U+"s.monthsRemaining=4;Math.random=()=>.10;caravanConvoyMonthTick();");assert.equal(run('__g.convoys.delivered'),1);assert.equal(run('__g.convoys.ambushes'),0);});
test('v50 extra road encounters are not generated by duplicate monthly ticks',()=>{const {run}=game();run(setup+v50Road+"window.__id=__bandit.id;caravanConvoyMonthTick();");assert.equal(run('__g.convoys.ambushes'),1);assert.equal(run('__q.ambush.banditId'),run('__id'));});
test('v50 bandit payment must be affordable and does not cost a month on rejection',()=>{const {run}=game();run(setup+v50Road+"s.wealth=3;window.__m=s.monthsRemaining;window.__issue=caravanConvoyAmbushIssue('pay');window.__ok=caravanConvoyAmbushAction('pay');");assert.ok(run('__issue.includes("4 servet")'));assert.equal(run('__ok'),false);assert.equal(run('s.monthsRemaining'),run('__m'));assert.equal(run('__bandit.wealth>=0'),true);});
test('v50 toll moves exactly four real coins from player to the threatening NPC',()=>{const {run}=game();run(setup+v50Road+"window.__p=s.wealth;window.__b=__bandit.wealth;window.__oldTick=monthlyTick;monthlyTick=()=>{};Math.random=()=>.99;window.__ok=caravanConvoyAmbushAction('pay');monthlyTick=__oldTick;");assert.equal(run('__ok'),true);assert.equal(run('s.wealth'),run('__p-4'));assert.equal(run('__bandit.wealth'),run('__b+4'));assert.equal(run('__g.convoys.tollsPaid'),4);assert.equal(run('__g.convoys.ambushPaid'),1);});
test('v50 successful toll and ordinary settlement conserve money among actual people',()=>{const {run}=game();run(setup+v50Road+"window.__total=s.wealth+__seller.wealth+__buyer.wealth+__bandit.wealth;window.__oldTick=monthlyTick;monthlyTick=()=>{};Math.random=()=>.99;caravanConvoyAmbushAction('pay');monthlyTick=__oldTick;caravanConvoyMonthTick();");assert.equal(run('s.wealth+__seller.wealth+__buyer.wealth+__bandit.wealth'),run('__total'));assert.equal(run('__g.convoys.delivered'),1);});
test('v50 unescorted resistance can repel a bandit without paying money',()=>{const {run}=game();run(setup+v50Road+"window.__cash=s.wealth;window.__oldTick=monthlyTick;monthlyTick=()=>{};Math.random=()=>0;window.__ok=caravanConvoyAmbushAction('resist');monthlyTick=__oldTick;caravanConvoyMonthTick();");assert.equal(run('__ok'),true);assert.equal(run('__g.convoys.ambushRepelled'),1);assert.equal(run('__g.convoys.ambushLost'),0);assert.equal(run('s.wealth'),run('__cash+__q.commission'));});
test('v50 resistance failure destroys actual cargo and refunds NPC buyer escrow',()=>{const {run}=game();run(setup+v50Road+"window.__buyerCash=__buyer.wealth;window.__oldTick=monthlyTick;monthlyTick=()=>{};Math.random=()=>.99;caravanConvoyAmbushAction('resist');monthlyTick=__oldTick;");assert.equal(run('__g.convoys.lost'),1);assert.equal(run('__g.convoys.ambushLost'),1);assert.equal(run('__buyer.wealth'),run('__buyerCash+__q.price'));assert.equal(run('caravanRivalUnits(__sr)'),1);assert.equal(run('caravanRivalUnits(__br)'),0);});
test('v50 insured resistance loss pays the insurer actual reserve only once',()=>{const {run}=game();run(setup+v47S+"s.monthsRemaining=7;Math.random=()=>.10;caravanConvoyMonthTick();window.__reserve=__q.insurance.coverage;window.__claims=__g.convoys.claimsPaid;Math.random=()=>.99;caravanConvoyAmbushAction('resist');window.__after=__g.convoys.claimsPaid;caravanConvoyMonthTick();");assert.equal(run('__after'),run('__claims+__reserve'));assert.equal(run('__g.convoys.claimsPaid'),run('__after'));assert.equal(run('__g.convoys.lost'),1);});
test('v50 ignoring an NPC demand for two game months forfeits actual cargo',()=>{const {run}=game();run(setup+v50Road+"s.monthsRemaining=5;caravanConvoyMonthTick();");assert.equal(run('__g.convoys.ambushExpired'),1);assert.equal(run('__g.convoys.lost'),1);assert.equal(run('__g.convoys.active'),null);});
test('v50 dead robber unblocks the road without transferring invented coins',()=>{const {run}=game();run(setup+v50Road+"window.__cash=s.wealth;__bandit.alive=false;Math.random=()=>.99;caravanConvoyMonthTick();");assert.equal(run('__q.ambush'),null);assert.equal(run('__g.convoys.lost'),0);assert.equal(run('__g.convoys.ambushes'),1);assert.equal(run('s.wealth'),run('__cash'));});
test('v50 insurance premiums do not pay for a robber when the player bargains',()=>{const {run}=game();run(setup+v47S+"s.monthsRemaining=7;Math.random=()=>.10;caravanConvoyMonthTick();window.__bank=__ins.wealth;window.__bandit=npcById(__q.ambush.banditId);window.__banditCash=__bandit.wealth;window.__oldTick=monthlyTick;monthlyTick=()=>{};Math.random=()=>.99;caravanConvoyAmbushAction('pay');monthlyTick=__oldTick;caravanConvoyMonthTick();");assert.equal(run('__ins.wealth'),run('__bank+__q.insurance.coverage'));assert.equal(run('__bandit.wealth'),run('__banditCash+4'));assert.equal(run('__g.convoys.claimsPaid'),0);});
test('v50 speedup and escort choices cannot bypass the blocked convoy',()=>{const {run}=game();run(setup+v50Road+"window.__why=caravanConvoyInterveneIssue('expedite');");assert.ok(run('__why.includes("yol kesici")'));});
test('v50 UI shows a named actor and the pay or resist controls',()=>{const {run}=game();run(setup+v50Road+"window.__html=caravanConvoySummaryHtml();");assert.ok(run('__html.includes("Yol kesildi")'));assert.ok(run('__html.includes(__bandit.name)'));assert.ok(run('__html.includes("Geçiş bedelini öde")'));assert.ok(run('__html.includes("Direnmeyi emret")'));assert.equal(run('__html.includes("Acele haberci gönder")'),false);});
test('v50 a saved roadside ambush retains the real NPC identity and deadline',()=>{const {run}=game();run(setup+v50Road+"window.__id=__bandit.id;window.__start=__q.ambush.startedSerial;save();load();");assert.equal(run('ensureCaravanTrade().guild.convoys.active.ambush.banditId'),run('__id'));assert.equal(run('ensureCaravanTrade().guild.convoys.active.ambush.startedSerial'),run('__start'));assert.ok(run('npcById(__id)?.alive'));});
test('v50 tampered impostor seller cannot be loaded as the road robber',()=>{const {run}=game();run(setup+v50Road+"__q.ambush={banditId:__seller.id,startedSerial:lifeSerial()};ensureCaravanTrade();");assert.equal(run('__g.convoys.active.ambush'),null);});
test('v50 old v49 saves upgrade without inventing a roadside ambush',()=>{const {run,storage}=game();run(setup+v49U+"s.version=49;delete __q.ambush;delete __q.ambushHandled;delete __g.convoys.ambushes;save();load();");assert.equal(run('s.version'),50);assert.ok(storage.has('yazgi_before_v50'));assert.equal(run('ensureCaravanTrade().guild.convoys.active.ambush'),null);assert.equal(run('ensureCaravanTrade().guild.convoys.ambushes'),0);});
test('v50 heirs retain robbery outcomes but not open encounters',()=>{const {run}=game();run(setup+v50Road+"window.__child=caravanInheritance(s,{assets:['caravan_share']});");assert.equal(run('__child.guild.convoys.active'),null);assert.equal(run('__child.guild.convoys.ambushes'),1);});
